&lt;PropertyGroup&gt;
    &lt;!-- 使用 partial 模式渐进迁移 --&gt;
    &lt;TrimMode&gt;partial&lt;/TrimMode&gt;

    &lt;!-- 仅裁剪标记为 IsTrimmable 的程序集 --&gt;
    &lt;!-- 未标记的程序集完整保留 --&gt;
&lt;/PropertyGroup&gt;

&lt;ItemGroup&gt;
    &lt;!-- 确保关键程序集不被过度裁剪 --&gt;
