public class GamepadInputAdapter : IInputProvider
{
    public Vector2 GetMovement() =&gt; new(Input.GetAxis(&quot;Horizontal_Gamepad&quot;), Input.GetAxis(&quot;Vertical_Gamepad&quot;));
