// 使用：同一个 Builder 类，不同流程产出不同角色
var director = new CharacterDirector();
var archer = director.BuildArcher(new CharacterBuilder(), &quot;Elf&quot;);
var warrior = director.BuildWarrior(new CharacterBuilder(), &quot;Human&quot;);
游戏开发深度
ScriptableObject Builder：策划可配置的构建步骤
Unity 中 Builder 的一大应用场景：用 ScriptableObject 定义”构建步骤的配置”，策划在 Inspector 里配每个步骤用什么资源：
// 构建步骤配置——每个 SO 实例定义一个步骤
public abstract class BuildStepSO : ScriptableObject
{
    public abstract void Apply(Character target);
}

[CreateAssetMenu(menuName = &quot;Build/Apply Race&quot;)]
public class ApplyRaceStep : BuildStepSO
{
    public string raceName;
    public int baseHp;
    public float baseSpeed;
    public override void Apply(Character target)
    {
        target.Race = raceName;
        target.Hp = baseHp;
        target.Speed = baseSpeed;
    }
}

[CreateAssetMenu(menuName = &quot;Build/Apply Equipment&quot;)]
public class ApplyEquipmentStep : BuildStepSO
{
    public GameObject weaponPrefab;
    public GameObject armorPrefab;
    public override void Apply(Character target)
    {
        target.WeaponPrefab = weaponPrefab;
        target.ArmorPrefab = armorPrefab;
    }
}

// SO 驱动的 Builder——策划在 Inspector 里拖入步骤
[CreateAssetMenu(menuName = &quot;Build/Character Builder&quot;)]
public class CharacterBuilderSO : ScriptableObject
{
    public BuildStepSO[] steps; // 策划排好顺序的构建步骤

    public Character Build()
    {
        var character = new Character();
        foreach (var step in steps)
            step.Apply(character);
        return character;
    }
}



                  SO Builder vs 纯代码 Builder 



SO Builder 的步骤是策划可配的——新增一种”初始装备”步骤不需要写代码，只需在 Inspector 里加一个 ApplyEquipmentStep SO。纯代码 Builder 适合有复杂逻辑判断的构建步骤（如”如果种族是精灵则自动加 MP”）。


Addressable 链式加载：步骤化异步 Builder
当构建步骤涉及异步资源加载时，Builder 每一步都可以是异步的：
public class AsyncCharacterBuilder
{
    private string _race;
    private string _class;
    private string _weaponAddress; // Addressable key
    private string _armorAddress;

    public AsyncCharacterBuilder WithRace(string race) { _race = race; return this; }
    public AsyncCharacterBuilder WithClass(string cls) { _class = cls; return this; }
    public AsyncCharacterBuilder WithWeaponAddress(string addr) { _weaponAddress = addr; return this; }
    public AsyncCharacterBuilder WithArmorAddress(string addr) { _armorAddress = addr; return this; }

    public async Task&lt;Character&gt; BuildAsync()
    {
        var character = new Character { Race = _race, Class = _class };

        // 并行加载所有 Addressable 资源
        var weaponTask = Addressables.LoadAssetAsync&lt;GameObject&gt;(_weaponAddress).Task;
        var armorTask  = Addressables.LoadAssetAsync&lt;GameObject&gt;(_armorAddress).Task;

        await Task.WhenAll(weaponTask, armorTask);

        character.WeaponPrefab = weaponTask.Result;
        character.ArmorPrefab  = armorTask.Result;

        return character;
    }
}

// 使用
var hero = await new AsyncCharacterBuilder()
    .WithRace(&quot;Elf&quot;)
    .WithClass(&quot;Archer&quot;)
    .WithWeaponAddress(&quot;Weapons/Longbow&quot;)
    .WithArmorAddress(&quot;Armors/Leather&quot;)
    .BuildAsync();



                  异步 Builder 的 Build 阶段是&quot;汇聚点&quot; 



同步 Builder 的每一步都是立即执行的；异步 Builder 的步骤只记录参数，BuildAsync 时统一加载。这种”延迟到 Build 时执行”的设计使得步骤间可以做优化（如并行加载）。详见 unitask-deep-dive-深入 的异步构建模式。


与工厂方法的关键区分








































维度factory-method-工厂方法builder-pattern-生成器目的创建一个对象分步构建复杂对象创建方式一步完成多步骤，每步可选客户端知道什么只知道”要什么类型”知道”怎么组装”产品复杂度简单对象多参数、多步骤对象步骤控制无有（Director 或链式调用）典型形态ISpawner.CreateEnemy()builder.WithRace().WithClass().Build()



                  简单判断法 



对象只有 2-3 个必填参数 → 构造函数或工厂方法；对象有大量可选参数或构建步骤有顺序约束 → Builder。Builder 的本质是用代码表达”先做什么、后做什么”。


Builder + Prototype：模板化构建
Builder 与 prototype-pattern-原型 组合：从模板克隆后，再用 Builder 微调：
public class TemplateCharacterBuilder
{
    private Character _template;

    public TemplateCharacterBuilder FromTemplate(Character template)
    {
        _template = template.DeepClone(); // 原型克隆
        return this;
    }

    public TemplateCharacterBuilder WithName(string name) { _template.Name = name; return this; }
    public TemplateCharacterBuilder WithLevel(int level) { _template.Level = level; return this; }

    public Character Build() =&gt; _template;
}

// 使用：从模板快速创建变体
var boss = new TemplateCharacterBuilder()
    .FromTemplate(goblinTemplate) // 克隆哥布林模板
    .WithName(&quot;Goblin King&quot;)     // 微调
    .WithLevel(50)
    .Build();



                  原型提供&quot;起点&quot;，Builder 提供&quot;微调&quot; 



单独用原型只能做完整克隆；单独用 Builder 每次都从零开始。两者组合：原型给出 80% 的初始状态，Builder 覆盖 20% 的差异。这比纯 Builder 从零构建效率更高。


Builder 创建不可变对象
C# 中用 Builder 创建 record 或只读对象，保证构建完成后不可修改：
// 不可变产品——所有属性只有 getter
public record GameConfig(
    string GameName,
    int MaxPlayers,
    float TickRate,
    bool EnablePvP,
    string MapName
);

// Builder——分步设置参数，Build 时一次性创建不可变 record
public class GameConfigBuilder
{
    private string _gameName = &quot;Default&quot;;
    private int _maxPlayers = 16;
    private float _tickRate = 60f;
    private bool _enablePvP = false;
    private string _mapName = &quot;Arena&quot;;

    public GameConfigBuilder WithGameName(string name) { _gameName = name; return this; }
    public GameConfigBuilder WithMaxPlayers(int max) { _maxPlayers = max; return this; }
    public GameConfigBuilder WithTickRate(float rate) { _tickRate = rate; return this; }
    public GameConfigBuilder WithPvP(bool enable) { _enablePvP = enable; return this; }
    public GameConfigBuilder WithMap(string map) { _mapName = map; return this; }

    public GameConfig Build() =&gt; new(_gameName, _maxPlayers, _tickRate, _enablePvP, _mapName);
}



                  record + with 表达式是 C# 10+ 的轻量替代 



如果不需要 Director 复用构建流程，C# 10 的 record + with 表达式可以替代 Builder：
var config = new GameConfig(&quot;MyGame&quot;, 16, 60f, false, &quot;Arena&quot;)
    with { EnablePvP = true, MaxPlayers = 32 };
但 with 只能覆盖已有属性，无法表达”步骤顺序约束”或”校验逻辑”。需要这两者时仍用 Builder。


变体与演进








































变体说明适用场景流畅接口 Builder链式调用 WithX().WithY().Build()C# 最常见形态，可读性优先泛型 BuilderBuilder&lt;TProduct&gt; 通用构建器多种产品共享构建模式步骤化异步 BuilderBuildAsync() 返回 Task&lt;T&gt;Addressable 加载、网络请求SO 驱动 BuilderScriptableObject 定义步骤配置策划可配，无需改代码模板 BuilderBuilder + prototype-pattern-原型 组合从模板克隆后微调不可变 BuilderBuilder 创建 record 或只读对象配置对象、不可变状态
流畅接口 Builder——最常见形态，完整示例：
public class LevelBuilder
{
    private string _name = &quot;Untitled&quot;;
    private Vector3 _spawnPoint = Vector3.zero;
    private readonly List&lt;GameObject&gt; _enemies = new();
    private readonly List&lt;GameObject&gt; _items = new();
    private AudioClip _bgm;

    public LevelBuilder WithName(string name) { _name = name; return this; }
    public LevelBuilder WithSpawnPoint(Vector3 pos) { _spawnPoint = pos; return this; }
    public LevelBuilder AddEnemy(GameObject prefab) { _enemies.Add(prefab); return this; }
    public LevelBuilder AddItem(GameObject prefab) { _items.Add(prefab); return this; }
    public LevelBuilder WithBGM(AudioClip clip) { _bgm = clip; return this; }

    public Level Build()
    {
        var level = new Level(_name, _spawnPoint, _enemies, _items, _bgm);
        return level;
    }
}

// 链式调用——可读性极佳
var level = new LevelBuilder()
    .WithName(&quot;Forest Dungeon&quot;)
    .WithSpawnPoint(new Vector3(0, 1, 0))
    .AddEnemy(goblinPrefab)
    .AddEnemy(wolfPrefab)
    .AddItem(healthPotionPrefab)
    .WithBGM(forestBGM)
    .Build();
泛型 Builder示例：
public abstract class Builder&lt;TProduct&gt; where TProduct : class, new()
{
    protected readonly TProduct _product = new();

    public abstract TProduct Build();

    // 通用初始化回调
    protected TProduct BuildCore() =&gt; _product;
}

public class CharacterBuilder2 : Builder&lt;Character&gt;
{
    public CharacterBuilder2 WithRace(string race) { _product.Race = race; return this; }
    public CharacterBuilder2 WithClass(string cls) { _product.Class = cls; return this; }
    public CharacterBuilder2 WithWeapon(string weapon) { _product.Weapon = weapon; return this; }

    public override Character Build() =&gt; BuildCore();
}



                  泛型 Builder 的局限 



泛型基类提供 _product 字段和 BuildCore() 方法，但每个具体 Builder 的 WithXxx 方法仍需手写（因为每种类别的可选参数不同）。泛型解决的是”公共基础设施”，不是”消除样板”。


步骤化异步 Builder——逐步加载资源：
public class AsyncLevelBuilder
{
    private string _name;
    private string _sceneAddress; // Addressable scene key
    private string _bgmAddress;

    public AsyncLevelBuilder WithName(string name) { _name = name; return this; }
    public AsyncLevelBuilder WithScene(string address) { _sceneAddress = address; return this; }
    public AsyncLevelBuilder WithBGM(string address) { _bgmAddress = address; return this; }

    public async Awaitable&lt;Level&gt; BuildAsync() // Unity Awaitable
    {
        var sceneOp = Addressables.LoadSceneAsync(_sceneAddress);
        var bgmOp   = Addressables.LoadAssetAsync&lt;AudioClip&gt;(_bgmAddress);

        await Awaitable.WhenAll(sceneOp.ToAwaitable(), bgmOp.ToAwaitable());

        return new Level(_name, sceneOp.Result, bgmOp.Result);
    }
}
反模式



                  Builder 过度抽象：简单对象不需要 Builder 



只有 2-3 个参数且没有步骤顺序约束的对象，用 Builder 是过度设计——用命名参数、可选参数或 record + with 即可。Builder 的价值在于”步骤多、有约束、需复用流程”，不是”每个类都配一个 Builder”。
// 反面教材：3 个参数的对象用 Builder——多此一举
public class Vector3Builder
{
    private float _x, _y, _z;
    public Vector3Builder WithX(float x) { _x = x; return this; }
    public Vector3Builder WithY(float y) { _y = y; return this; }
    public Vector3Builder WithZ(float z) { _z = z; return this; }
    public Vector3 Build() =&gt; new(_x, _y, _z);
}
// 直接 new Vector3(x, y, z) 不好吗？





                  Builder 内部状态不一致：未调用必要步骤就 Build 



Builder 没有”强制调用顺序”的机制——客户端可能忘了设必填字段就调用 Build()。防御方式：

Build() 中校验必填字段，缺失时抛异常
用”阶段性 Builder”在类型系统层面强制顺序（见下方示例）

// 阶段性 Builder：类型系统强制步骤顺序
public class CharacterBuilderPhase1  // 必须先设 Race
{
    public CharacterBuilderPhase2 WithRace(string race) =&gt; new(race);
}
public class CharacterBuilderPhase2  // 然后设 Class
{
    private readonly string _race;
    public CharacterBuilderPhase2(string race) =&gt; _race = race;
    public CharacterBuilderFinal WithClass(string cls) =&gt; new(_race, cls);
}
public class CharacterBuilderFinal  // 最后才能 Build
{
    private readonly string _race;
    private readonly string _class;
    private string _weapon;
    public CharacterBuilderFinal(string race, string cls) { _race = race; _class = cls; }
    public CharacterBuilderFinal WithWeapon(string weapon) { _weapon = weapon; return this; }
    public Character Build() =&gt; new() { Race = _race, Class = _class, Weapon = _weapon };
}
// 不可能漏掉 Race 或 Class——编译期就保证
var hero = new CharacterBuilderPhase1().WithRace(&quot;Elf&quot;).WithClass(&quot;Archer&quot;).WithWeapon(&quot;Bow&quot;).Build();





                  Builder 复用导致状态泄漏 



// 反面教材：同一个 Builder 实例 Build 两次——第二次 Build 带着第一次的状态
var builder = new CharacterBuilder().WithRace(&quot;Elf&quot;);
var hero1 = builder.WithClass(&quot;Archer&quot;).Build();
var hero2 = builder.WithClass(&quot;Warrior&quot;).Build();
// hero2 的 Race 还是 &quot;Elf&quot;——可能不是预期行为
Builder 设计有两种选择：(1) 每次 Build() 后 Builder 不可复用（抛异常或重置）；(2) Build() 内部深拷贝 product，Builder 可复用。明确选择一种并在文档中标注。


实践示例

角色创建流程：种族 → 职业 → 初始装备 → 属性
关卡构建：地形 → 敌人 → 道具 → 触发器
Unity Inspector 本质上就是一个 Builder UI——每个字段就是一个构建步骤
网络协议消息构建：Header → Body → Checksum
技能效果链构建：主效果 → Buff → Debuff → 特效
配置对象构建：从 JSON/ScriptableObject 读取参数，Builder 校验后构建不可变配置

权衡与选择

用生成器：对象有很多可选参数、构建步骤有顺序要求时
用工厂方法：对象简单、创建逻辑一步完成时——factory-method-工厂方法
用抽象工厂：需要创建一族相关对象时——abstract-factory-抽象工厂 保证族一致性
用原型：已有模板实例、克隆更方便时——prototype-pattern-原型 适合 Prefab 克隆
直接 new / record with：参数少且无步骤约束时——不要过度设计
用组合模式：Builder 构建的对象本身是树形结构时——composite-pattern-组合

常见陷阱



                  Builder 需要维护一个与产品平行的 Builder 类 



产品字段变化时 Builder 也要同步修改。如果产品很简单（3 个以下参数），Builder 是过度设计——用命名参数或 record 即可。





                  Director 与 Builder 强耦合 



Director 如果依赖具体 Builder 而非 IBuilder 接口，就失去了”同样流程不同表示”的能力。Director 应只依赖 IBuilder 接口。





                  异步 Builder 的异常处理 



BuildAsync() 中任何一步异步操作都可能失败。必须在 await 处加 try-catch，或在 Builder 层面提供回退逻辑（如资源加载失败时使用默认资源）。


