patterns-设计模式/chain-of-responsibility-责任.content:
责任链（Chain of Responsibility）
核心思想
将请求沿处理者链传递，每个处理者可处理请求或将其传递给下一个。解耦发送者与接收者——发送者不知道链的长度、顺序和哪个处理者最终会处理。
结构图
classDiagram
    class IHandler {
        &lt;&lt;interface&gt;&gt;
        +SetNext(handler: IHandler) IHandler
        +Handle(request: Request) Response
    }
    class ConcreteHandlerA {
        -_next: IHandler
        +SetNext(handler: IHandler) IHandler
        +Handle(request: Request) Response
    }
    class ConcreteHandlerB {
        -_next: IHandler
        +SetNext(handler: IHandler) IHandler
        +Handle(request: Request) Response
    }
    class ConcreteHandlerC {
        -_next: IHandler
        +SetNext(handler: IHandler) IHandler
        +Handle(request: Request) Response
    }
    class Client {
        +SendRequest(handler: IHandler, request: Request)
    }

    IHandler &lt;|.. ConcreteHandlerA
    IHandler &lt;|.. ConcreteHandlerB
    IHandler &lt;|.. ConcreteHandlerC
    ConcreteHandlerA --&gt; IHandler : _next
    ConcreteHandlerB --&gt; IHandler : _next
    ConcreteHandlerC --&gt; IHandler : _next
    Client --&gt; IHandler : 只知道链头

sequenceDiagram
    participant Client
    participant HandlerA as 护盾处理者
    participant HandlerB as 护甲处理者
    participant HandlerC as 血量处理者

    Client-&gt;&gt;HandlerA: Handle(damage=30)
    HandlerA-&gt;&gt;HandlerA: 吸收20伤害
    HandlerA-&gt;&gt;HandlerB: Handle(damage=10)
    HandlerB-&gt;&gt;HandlerB: 减免5伤害
    HandlerB-&gt;&gt;HandlerC: Handle(damage=5)
    HandlerC-&gt;&gt;HandlerC: 扣除5血量
    HandlerC--&gt;&gt;Client: 最终受伤5

问题动机
没有责任链时，发送者必须知道所有潜在处理者的存在和顺序：
// 反面教材：发送者与所有处理者紧耦合
public class DamageReceiver : MonoBehaviour
{
    public Shield Shield;
    public Armor Armor;
    public Health Health;
    public Dodge Dodge;

    public void TakeDamage(int damage)
    {
        // 发送者必须知道处理顺序、存在性、逻辑
        if (Dodge.TryDodge()) return;
        damage = Shield.Absorb(damage);
        damage = Armor.Reduce(damage);
        Health.Apply(damage);
    }
}
这种写法的问题：

顺序硬编码：调整处理顺序需要修改 TakeDamage，无法运行时变更
增删处理者困难：新增一个”反伤”环节，必须改 TakeDamage 方法
无法复用管线：不同敌人可能有不同的处理管线（有的没有护盾、有的有魔法免疫），每种组合都需要一个新方法
测试困难：无法独立测试单个处理环节

责任链的核心动机：让发送者不需要知道”谁会处理”和”处理顺序”，每个处理者只关心自己的逻辑和”要不要往下传”。
参与者






























角色职责Unity/C# 对应IHandler声明处理接口和链构建方法IDamageHandler、IInputHandler 接口ConcreteHandler处理请求或传递给下一个ShieldHandler、ArmorHandler、HealthHandlerClient向链头发起请求伤害系统、输入管理器链构建逻辑运行时组装处理者顺序工厂方法或 ScriptableObject 配置
工作原理
基础实现：伤害处理管道
public abstract class DamageHandler
{
    private DamageHandler _next;
    public DamageHandler SetNext(DamageHandler next) { _next = next; return next; }

    public virtual int Handle(int damage)
    {
        return _next?.Handle(damage) ?? damage;
    }
}

public class ShieldHandler : DamageHandler
{
    private int _shield = 20;
    public override int Handle(int damage)
    {
        var absorbed = Mathf.Min(_shield, damage);
        _shield -= absorbed;
        Debug.Log($&quot;Shield absorbed {absorbed}&quot;);
        return base.Handle(damage - absorbed);
    }
}

public class ArmorHandler : DamageHandler
{
    private readonly int _armor;
    public ArmorHandler(int armor) =&gt; _armor = armor;

    public override int Handle(int damage)
    {
        var reduced = Mathf.Min(_armor, damage);
        Debug.Log($&quot;Armor reduced {reduced}&quot;);
        return base.Handle(damage - reduced);
    }
}

public class HealthHandler : DamageHandler
{
    private readonly Health _health;
    public HealthHandler(Health health) =&gt; _health = health;

    public override int Handle(int damage)
    {
        _health.Current -= damage;
        Debug.Log($&quot;Health lost {damage}&quot;);
        return damage; // 兜底：返回最终伤害
    }
}

// 组装链——顺序决定优先级
var chain = new ShieldHandler();
chain.SetNext(new ArmorHandler(5))
     .SetNext(new HealthHandler(playerHealth));
var finalDamage = chain.Handle(30); // 护盾20 → 护甲5 → 受伤5
请求上下文对象
当处理者之间需要共享信息（如修改前后的伤害值、伤害类型），用上下文对象替代裸参数：
public class DamageContext
{
    public int OriginalDamage;
    public int CurrentDamage;
    public DamageType Type;       // Physical, Magic, True
    public GameObject Attacker;
    public GameObject Target;
    public bool IsCancelled;       // 处理者可取消请求
}

public abstract class DamageHandler
{
    private DamageHandler _next;
    public DamageHandler SetNext(DamageHandler next) { _next = next; return next; }

    public virtual void Handle(DamageContext ctx)
    {
        if (!ctx.IsCancelled)
            _next?.Handle(ctx);
    }
}

// 魔法免疫处理者：直接取消魔法伤害
public class MagicImmuneHandler : DamageHandler
{
    public override void Handle(DamageContext ctx)
    {
        if (ctx.Type == DamageType.Magic)
        {
            Debug.Log(&quot;Magic damage cancelled&quot;);
            ctx.IsCancelled = true;
            return; // 不传递
        }
        base.Handle(ctx);
    }
}
