问题动机
反面教材：指针追逐——List&lt;Enemy&gt; 遍历导致 cache miss
不用数据局部性会怎样？对象引用分散在堆上，CPU 缓存频繁失效——“指针追逐”（chasing pointers）：
// 反面教材：List&lt;Enemy&gt; 遍历导致 cache miss
public class Enemy
{
    public Vector3 Position;    // 12 bytes
    public int Health;          // 4 bytes
    public float Speed;         // 4 bytes
    public AIState AIState;     // 4 bytes
    public string Name;         // 8 bytes（引用）
    public LootTable Loot;     // 8 bytes（引用）
    // 总计 ~40 bytes（含引用和填充）
}

// 1000 个 Enemy 在堆上随机分布
List&lt;Enemy&gt; enemies = new List&lt;Enemy&gt;();
// enemies[0] 在内存地址 0x1000
// enemies[1] 在内存地址 0x5800  ← 跳跃 18KB！
// enemies[2] 在内存地址 0x2400  ← 又跳回去
// List 本身连续，但每个元素是引用，指向堆上的随机位置

// 遍历更新位置：每访问一个 Enemy 都可能 Cache Miss
foreach (var enemy in enemies)
{
    // 每次访问 enemy.Position 都是指针跳转
    // CPU 等 100-200 个周期从主内存取数据
    // Cache Line 64 bytes ≈ 只装 1 个 Enemy 的部分字段
    // 遍历 1000 个 Enemy = 至少 500+ 次 Cache Miss
    enemy.Position += enemy.Speed * enemy.AIState.Direction * dt;
}

// 问题 1：热数据（Position/Speed）和冷数据（Name/Loot）混在一起，Cache 被冷数据&quot;稀释&quot;
// 问题 2：每次 CPU 请求 Position，加载的 Cache Line 里还包含 Name、Loot 等无关数据
// 问题 3：1000 个 Enemy 的遍历中 90% 的时间在等内存，而非在做计算
// 正面做法：SoA 布局，连续内存
public class EnemyData
{
    public NativeArray&lt;Vector3&gt; Positions;  // 连续 1000 个 Vector3
    public NativeArray&lt;int&gt; Healths;        // 连续 1000 个 int
    public NativeArray&lt;float&gt; Speeds;       // 连续 1000 个 float
    public NativeArray&lt;AIState&gt; AIStates;   // 连续 1000 个 AIState
}

// 遍历更新位置：线性扫描连续内存
for (int i = 0; i &lt; count; i++)
{
    // Positions[i] 和 Positions[i+1] 在同一 Cache Line
    // CPU 预取机制提前加载下一批数据
    // Cache Line 64 bytes ≈ 装 5 个 Vector3
    // 遍历 1000 个 = ~200 次 Cache Line 加载（vs AoS 的 ~500+ 次）
    positions[i] += speeds[i] * aiStates[i].Direction * dt;
}
