问题动机
反面教材：同步事件链导致无限递归
不用事件队列时，同步通知可能导致级联调用——A 通知 B，B 通知 C，C 又触发 A，形成死循环：
// 反面教材：同步事件链导致的无限递归
public class DamageSystem
{
    public event Action&lt;DamageInfo&gt; OnDamage;

    public void ApplyDamage(Entity target, int amount)
    {
        var info = new DamageInfo(target, amount);
        OnDamage?.Invoke(info); // 同步调用所有观察者

        // 观察者中可能再次触发伤害 → 递归！
    }
}

// 灾难场景：观察者中触发连锁反应
public class ThornsEffect
{
    private void OnDamageTaken(DamageInfo info)
    {
        // 反弹伤害 → 再次触发 OnDamage → 递归！
        _damageSystem.ApplyDamage(info.Source, info.Amount / 2);
    }
}

public class AudioEffect
{
    private void OnDamageTaken(DamageInfo info)
    {
        // 同步加载音效资源 → 阻塞当前帧！
        var clip = Resources.Load&lt;AudioClip&gt;(&quot;hit&quot;); // 同步加载，卡主线程
        AudioSource.PlayClipAtPoint(clip, Vector3.zero);
    }
}

// 问题 1：观察者 A 反弹伤害 → 再次触发 OnDamage → 无限递归 → StackOverflowException
// 问题 2：观察者 B 同步加载资源 → 阻塞所有后续观察者 → 帧卡顿
// 问题 3：观察者执行期间，当前帧的世界状态可能不一致（伤害已扣但死亡还没处理）
// 正面做法：事件队列——入队即返回，打破递归
public class DamageSystem
{
    private readonly EventQueue _eventQueue;

    public void ApplyDamage(Entity target, int amount)
    {
        // 只入队，不等待任何人处理
        _eventQueue.Enqueue(new DamageEvent(target, amount));
    }
}

// 消费者按自己的节奏、在安全的时机处理
public class DamageEventProcessor : MonoBehaviour
{
    private void Update()
    {
        // 每帧处理积压的事件，不会阻塞生产者
        _eventQueue.ProcessAll();
    }
}
参与者






























角色职责Unity/C# 对应生产者（Producer）产生事件并入队伤害系统、输入系统、网络层事件队列（Event Queue）存储待处理事件的 FIFO 缓冲区Queue&lt;T&gt;、ConcurrentQueue&lt;T&gt;消费者（Consumer）从队列取事件并处理音效系统、UI 更新、成就检测事件（Event）携带通知数据的值对象struct 事件（无 GC）
游戏开发深度
音频系统事件队列——播放音效不阻塞游戏逻辑
// 音频事件
public struct AudioEvent
{
    public string ClipName;
    public Vector3 Position;
    public float Volume;
}

// 音频系统作为消费者——异步处理，不阻塞战斗/逻辑
public class AudioSystem : MonoBehaviour
{
    private EventQueue&lt;AudioEvent&gt; _audioQueue;

    private void Update()
    {
        // 在安全的时机处理音频事件
        _audioQueue.ProcessAll();
    }

    private void OnAudioEvent(AudioEvent evt)
    {
        // 真正的音频播放——可以在此时异步加载
        Addressables.LoadAssetAsync&lt;AudioClip&gt;(evt.ClipName).Completed += op =&gt;
        {
            AudioSource.PlayClipAtPoint(op.Result, evt.Position, evt.Volume);
        };
    }
}

// 任何系统都可以安全地请求播放音频
public class CombatSystem : MonoBehaviour
{
    private EventQueue&lt;AudioEvent&gt; _audioQueue;

    public void OnHit(Entity target)
    {
        // 入队即返回，不会阻塞战斗逻辑
        _audioQueue.Enqueue(new AudioEvent
        {
            ClipName = &quot;hit_sword&quot;,
            Position = target.Position,
            Volume = 1f
        });
    }
}
成就系统事件队列——事件入队，延迟处理
// 成就系统：不需要即时响应，延迟处理即可
public class AchievementSystem : MonoBehaviour
{
    private Queue&lt;AchievementEvent&gt; _pendingEvents = new();
    private Dictionary&lt;string, int&gt; _progress = new();

    public void OnGameEvent(AchievementEvent evt)
    {
        // 入队但不立即检测——成就检测不是每帧的紧急任务
        _pendingEvents.Enqueue(evt);
    }

    private void Update()
    {
        // 每帧只处理少量事件，避免卡顿
        int processed = 0;
        while (_pendingEvents.Count &gt; 0 &amp;&amp; processed &lt; 10)
        {
            var evt = _pendingEvents.Dequeue();
            UpdateProgress(evt);
            processed++;
        }
    }
}
Unity 的 UnityEvent 与事件队列的区别



































维度UnityEvent事件队列通知方式同步（直接调用）异步（入队后延迟处理）生产者是否等待消费者是，所有监听者返回后才继续否，入队即返回递归风险高低（处理的是上一帧入队的事件）可在编辑器配置是否适用场景Inspector 拖拽回调、UI 交互跨系统、跨帧通信



                  选择标准 



需要 Inspector 可视化配置的 UI 回调 → UnityEvent。需要时序解耦、跨系统通信 → 事件队列。


用 UniTask/Channel 实现异步事件队列
参见 unitask-deep-dive-深入。UniTask 的 Channel&lt;T&gt; 提供了异步生产者-消费者模式，比手动队列更优雅：
// UniTask Channel：异步事件队列
public class AsyncEventQueue
{
    private readonly Channel&lt;GameEvent&gt; _channel = Channel.CreateSingleConsumerUnbounded&lt;GameEvent&gt;();

    public ChannelWriter&lt;GameEvent&gt; Writer =&gt; _channel.Writer;
    public ChannelReader&lt;GameEvent&gt; Reader =&gt; _channel.Reader;
}

// 生产者
public class GameSystem
{
    private ChannelWriter&lt;GameEvent&gt; _writer;

    public void FireEvent(GameEvent evt)
    {
        _writer.TryWrite(evt); // 非阻塞写入
    }
}

// 消费者：异步循环读取
public class EventConsumer : MonoBehaviour
{
    private async UniTaskVoid ProcessEventsAsync(ChannelReader&lt;GameEvent&gt; reader, CancellationToken ct)
    {
        await foreach (var evt in reader.ReadAllAsync(ct))
        {
            // 异步处理每个事件，不阻塞主线程
            switch (evt.Type)
            {
                case EventType.Damage: HandleDamage(evt); break;
                case EventType.Heal:   HandleHeal(evt);   break;
            }
        }
    }
}
环形缓冲区实现高性能事件队列（无 GC）
用固定大小的环形缓冲区替代 Queue&lt;T&gt;，避免动态扩容导致的 GC：
// 环形缓冲区事件队列——零 GC
public struct RingBufferEventQueue&lt;T&gt; where T : struct
{
    private T[] _buffer;
    private int _head; // 出队位置
    private int _tail; // 入队位置
    private int _count;
    private int _capacity;

    public RingBufferEventQueue(int capacity)
    {
        _capacity = capacity;
        _buffer = new T[capacity];
        _head = 0;
        _tail = 0;
        _count = 0;
    }

    public bool Enqueue(T evt)
    {
        if (_count &gt;= _capacity) return false; // 满了，丢弃
        _buffer[_tail] = evt;
        _tail = (_tail + 1) % _capacity;
        _count++;
        return true;
    }

    public bool Dequeue(out T evt)
    {
        if (_count == 0)
        {
            evt = default;
            return false;
        }
        evt = _buffer[_head];
        _head = (_head + 1) % _capacity;
        _count--;
        return true;
    }

    public int Count =&gt; _count;
}
变体与演进
事件队列演进路径
graph LR
    A[&quot;同步观察者&lt;br&gt;直接调用&quot;] --&gt; B[&quot;单播队列&lt;br&gt;一个生产者一个消费者&quot;]
    B --&gt; C[&quot;多播队列&lt;br&gt;一个事件多个消费者&quot;]
    C --&gt; D[&quot;优先级队列&lt;br&gt;按优先级出队&quot;]
    C --&gt; E[&quot;环形缓冲区&lt;br&gt;零 GC 固定大小&quot;]
    C --&gt; F[&quot;UniTask Channel&lt;br&gt;异步生产者-消费者&quot;]

变体对比








































变体特点适用场景单播队列只有一个消费者资源加载、命令队列多播队列多个消费者都收到音效、日志、成就优先级队列按优先级出队AI 决策（高优先级行为先处理）环形缓冲区固定大小，零 GC实时日志、高频粒子事件延迟事件队列事件在指定时间后处理技能冷却、延迟伤害双缓冲事件队列读写分离，处理期间仍可入队每帧数百个粒子事件
反模式



                  队列积压——消费速度跟不上生产 



如果消费者处理速度赶不上生产速度，队列会无限增长，最终内存溢出。必须设置容量上限或反压机制：


// 有界队列——满了丢弃或报警
public class BoundedEventQueue&lt;T&gt; where T : struct
{
    private readonly Queue&lt;T&gt; _queue = new();
    private readonly int _maxSize;

    public BoundedEventQueue(int maxSize = 1024) =&gt; _maxSize = maxSize;

    public bool Enqueue(T evt)
    {
        if (_queue.Count &gt;= _maxSize)
        {
            Debug.LogWarning($&quot;Event queue overflow! Dropping: {evt}&quot;);
            return false; // 策略 1：丢弃
        }
        _queue.Enqueue(evt);
        return true;
    }
}



                  事件丢失——满队列策略 



队列满时的事件丢失可能导致游戏逻辑不完整。对于关键事件（如伤害/死亡），不应丢弃——应使用阻塞等待或无界队列+监控。对于非关键事件（如音效/日志），丢弃是合理的。





                  在事件处理中再次入队导致无限循环 



消费者处理事件时又产生新事件入队，如果新事件又触发同一消费者 → 循环。解决方法：每帧只处理入队时已有的事件（ProcessAll 的 count 技巧），或设置最大处理轮次。


// 防止无限循环：只处理当前帧积压的事件
public void ProcessAll()
{
    int count = _queue.Count; // 先记数
    for (int i = 0; i &lt; count; i++)
    {
        var evt = _queue.Dequeue();
        foreach (var subscriber in _subscribers)
            subscriber(evt);
    }
    // 处理期间新入队的事件留到下一帧
}



                  事件顺序依赖 



多生产者场景下入队顺序不等于逻辑顺序。例如”先受伤后死亡”两个事件，如果来自不同线程，可能”死亡”先入队。解决：事件携带时间戳或序列号，消费者按序处理。


