参与者

























角色职责Unity/C# 对应Facade提供简化的高层接口，将客户端请求委托给适当子系统GameManager、AudioManager、AssetLoadingServiceSubsystem实现专业功能，不知道 Facade 的存在各个独立 Manager/System（AudioSystem、ParticleSystem、SpawnSystem）Client通过 Facade 与子系统交互，不直接引用子系统关卡脚本、UI 控制器、GameLoop



                  子系统不知道 Facade 的存在 



这是外观与中介者的关键区别。子系统不知道自己被外观包装了，它们仍然可以独立使用。外观是单向依赖——外观依赖子系统，子系统不依赖外观。


工作原理
基础实现：游戏初始化外观
// 多个子系统（各自独立、互不知道）
public class AudioSystem
{
    public void PlayBGM(string clip) =&gt; Debug.Log($&quot;Playing BGM: {clip}&quot;);
    public void PlaySFX(string clip) =&gt; Debug.Log($&quot;Playing SFX: {clip}&quot;);
    public void Initialize(AudioSettings settings) { /* ... */ }
}

public class ParticleSystem
{
    public void Emit(string effect) =&gt; Debug.Log($&quot;Emitting: {effect}&quot;);
    public void PrewarmCache() { /* ... */ }
}

public class SpawnSystem
{
    public GameObject SpawnEnemy(string type) =&gt; new(type);
    public void LoadEnemies(LevelData data) { /* ... */ }
}

public class UISystem
{
    public void ShowHUD() =&gt; Debug.Log(&quot;HUD shown&quot;);
    public void ShowBossHPBar() =&gt; Debug.Log(&quot;Boss HP bar shown&quot;);
}

// 外观：统一入口，封装子系统协作逻辑
public class LevelFacade
{
    private readonly AudioSystem _audio = new();
    private readonly ParticleSystem _particles = new();
    private readonly SpawnSystem _spawner = new();
    private readonly UISystem _ui = new();

    public void StartBossFight()
    {
        _audio.PlayBGM(&quot;boss_theme&quot;);
        _audio.PlaySFX(&quot;boss_roar&quot;);
        _particles.Emit(&quot;dramatic_entrance&quot;);
        _spawner.SpawnEnemy(&quot;DragonBoss&quot;);
        _ui.ShowBossHPBar();
    }

    public void CompleteLevel()
    {
        _audio.PlayBGM(&quot;victory_theme&quot;);
        _particles.Emit(&quot;confetti&quot;);
        _ui.ShowHUD(); // 切换到结算界面
    }
}
