工作原理
基础实现：森林系统
// 内在状态：共享的树模型数据（不可变）
public class TreeModel  // Flyweight
{
    public string MeshName { get; }
    public string TextureName { get; }
    public float DefaultHeight { get; }

    public TreeModel(string mesh, string texture, float height)
    {
        MeshName = mesh;
        TextureName = texture;
        DefaultHeight = height;
    }

    // 操作接受外在状态参数
    public void Render(Vector3 position, float scale = 1f)
        =&gt; Debug.Log($&quot;Tree at {position}, mesh={MeshName}, scale={scale}&quot;);
}

// 享元工厂：缓存共享对象
public class TreeModelFactory
{
    private static readonly Dictionary&lt;string, TreeModel&gt; _cache = new();

    public static TreeModel GetModel(string type) =&gt;
        _cache.TryGetValue(type, out var model)
            ? model
            : _cache[type] = new TreeModel(
                $&quot;{type}_mesh&quot;, $&quot;{type}_tex&quot;, GetDefaultHeight(type));

    private static float GetDefaultHeight(string type) =&gt; type switch
    {
        &quot;Oak&quot; =&gt; 8f,
        &quot;Pine&quot; =&gt; 12f,
        &quot;Bush&quot; =&gt; 2f,
        _ =&gt; 5f
    };
}

// 外在状态：每棵树的独有位置和缩放
public class Tree  // Context
{
    public Vector3 Position { get; }     // 外在状态
    public float Scale { get; }          // 外在状态
    public TreeModel Model { get; }      // 共享享元

    public Tree(Vector3 position, string modelType, float scale = 1f)
    {
        Position = position;
        Scale = scale;
        Model = TreeModelFactory.GetModel(modelType); // 共享！
    }

    public void Render() =&gt; Model.Render(Position, Scale);
}
使用：10000 棵树共享 3 个 TreeModel
public class Forest : MonoBehaviour
{
    private readonly List&lt;Tree&gt; _trees = new();

    private void Start()
    {
        var random = new System.Random();
        string[] types = { &quot;Oak&quot;, &quot;Pine&quot;, &quot;Bush&quot; };

        for (int i = 0; i &lt; 10000; i++)
        {
            var pos = new Vector3(random.Next(-500, 500), 0, random.Next(-500, 500));
            var type = types[random.Next(types.Length)];
            _trees.Add(new Tree(pos, type));
        }

        // 内存占用：3 个 TreeModel + 10000 个 Tree（每个只存 position + scale + 引用）
        // 而非 10000 份完整的树模型数据
    }
}
游戏开发深度
Tile 地图共享地形数据
Tile 地图是享元模式的经典场景——同类型 Tile 共享纹理、碰撞形状、移动消耗等数据，每个 Tile 实例只存坐标：
// 享元：Tile 类型数据（共享）
public class TileType  // Flyweight
{
    public string Name { get; }
    public int SpriteIndex { get; }
    public bool IsWalkable { get; }
    public float MovementCost { get; }
    public int CollisionMask { get; }

    public TileType(string name, int sprite, bool walkable, float cost, int collision)
    {
        Name = name;
        SpriteIndex = sprite;
        IsWalkable = walkable;
        MovementCost = cost;
        CollisionMask = collision;
    }
}

// 享元工厂
public static class TileTypeRegistry
{
    private static readonly Dictionary&lt;string, TileType&gt; _types = new();

    public static TileType Get(string name) =&gt;
        _types.TryGetValue(name, out var t) ? t : _types[name] = LoadFromConfig(name);

    private static TileType LoadFromConfig(string name) { /* 从配置加载 */ }
}

// 上下文：地图中每个格子只存坐标和享元引用
public struct MapCell  // 外在状态极简
{
    public int X, Y;
    public TileType Type;  // 共享引用
}



                  用 struct 存外在状态 



Tile 地图中格子的外在状态（坐标+享元引用）非常小，用 struct 而非 class 可以进一步减少内存——没有对象头开销，数组连续存储对 CPU 缓存友好。这与 native-container-Native容器 中 NativeArray 的设计理念一致。


弹幕系统共享弹丸配置
弹幕游戏中同一种弹丸可能同时存在数千发，它们的弹道速度、伤害、颜色完全相同，只有位置和方向不同：
// 享元：弹丸配置（共享）
public class BulletConfig  // Flyweight
{
    public string Name { get; }
    public float Speed { get; }
    public float Damage { get; }
    public Color Color { get; }
    public float Radius { get; }
    public string SpriteKey { get; }

    public BulletConfig(string name, float speed, float damage, Color color, float radius, string sprite)
    {
        Name = name;
        Speed = speed;
        Damage = damage;
        Color = color;
        Radius = radius;
        SpriteKey = sprite;
    }
}

// 外在状态：弹丸实例只存位置和方向
public struct Bullet  // struct 减少内存
{
    public Vector2 Position;   // 外在状态
    public Vector2 Direction;   // 外在状态
    public BulletConfig Config; // 共享享元引用
    public float Lifetime;     // 外在状态

    public void Update(float dt)
    {
        Position += Direction * Config.Speed * dt;
        Lifetime -= dt;
    }
}

// 享元工厂
public static class BulletConfigFactory
{
    private static readonly Dictionary&lt;string, BulletConfig&gt; _configs = new();

    public static BulletConfig Get(string name) =&gt;
        _configs.TryGetValue(name, out var c)
            ? c
            : _configs[name] = Resources.Load&lt;BulletConfigSO&gt;($&quot;Bullets/{name}&quot;).ToConfig();
}



                  弹幕系统中享元与对象池常组合使用 



享元共享配置数据（1 份），对象池复用 Bullet 实例（N 份但避免 GC）。详见”变体与演进”章节。


ScriptableObject 作为享元载体
Unity 中 ScriptableObject 天然适合充当享元——它是独立于场景的数据容器，多个 MonoBehaviour 可以引用同一个 SO 实例，实现数据共享：
[CreateAssetMenu(menuName = &quot;Config/Enemy Type&quot;)]
public class EnemyTypeSO : ScriptableObject  // Flyweight
{
    public string typeName;
    public GameObject prefab;         // 共享的预制体
    public float maxHealth;           // 共享的属性
    public float moveSpeed;           // 共享的属性
    public float attackDamage;        // 共享的属性
    public ElementalType element;     // 共享的属性
    public LootTableSO lootTable;     // 共享的掉落表
}

public class Enemy : MonoBehaviour  // Context
{
    public Vector3 SpawnPosition;    // 外在状态
    public float CurrentHealth;      // 外在状态（当前血量，非最大血量）
    public EnemyTypeSO Type;         // 共享享元引用

    public void Initialize(EnemyTypeSO type, Vector3 spawnPos)
    {
        Type = type;
        SpawnPosition = spawnPos;
        CurrentHealth = type.maxHealth; // 从共享数据初始化
    }
}



                  SO 享元 vs 纯 C# 享元 



SO 享元的优势：Inspector 可视化编辑、运行时热重载、资源引用自动管理。劣势：加载依赖 Unity 资源管线，无法在非 MonoBehaviour 上下文中使用。纯 C# 享元更轻量，适合 DOTS/Burst 编译环境。


DOTS Archetype 与享元思想的对应
DOTS 中的 EntityArchetype 体现了享元思想——Archetype 定义了 Entity 的”组件配方”（内在结构），同 Archetype 的 Entity 在内存中连续排列：
// Archetype = 内在状态的结构定义（享元）
var zombieArchetype = entityManager.CreateArchetype(
    typeof(Health),       // 组件 = 内在状态的分类
    typeof(MovementSpeed),
    typeof(AiTagZombie)
);

// 所有同 Archetype 的 Entity 共享内存布局
// 组件数据按 Archetype 分块存储（chunk），缓存友好
var entity1 = entityManager.CreateEntity(zombieArchetype);
var entity2 = entityManager.CreateEntity(zombieArchetype);
// entity1 和 entity2 的 Health、MovementSpeed 值可以不同（外在状态）
// 但它们的内存布局完全相同（内在结构共享）



                  Archetype = 结构共享 + 数据分离 



Archetype 不是经典的享元模式——它共享的是”结构”而非”数据”。但核心思想一致：识别共性、分离差异。详见 dots-ecs-数据导向。


享元与对象池的区分（关键！）
两者经常被混淆，但本质完全不同：








































维度享元（Flyweight）对象池（Object Pool）核心目的减少内存占用（共享同一份数据）减少 GC 压力（复用实例避免分配销毁）对象身份多个客户端持有同一个对象引用池中对象是独立实例，每次 Rent 返回不同实例状态特征内在状态不可变池对象的状态每次 Rent 后重置生命周期享元一旦创建通常不销毁池对象频繁 Rent/Return数量关系1 个享元 → N 个客户端共享N 个池对象 → 同一时刻最多 N 个客户端使用典型场景同类型 Tile 数据、弹丸配置子弹实例、特效粒子、敌人实例
// 享元：多个 Bullet 引用同一个 Config
BulletConfig config = BulletConfigFactory.Get(&quot;Fireball&quot;); // 只有一份
Bullet b1 = new Bullet { Config = config, Position = pos1 }; // 共享 config
Bullet b2 = new Bullet { Config = config, Position = pos2 }; // 共享 config
// b1.Config == b2.Config → true（同一个对象）

// 对象池：每次 Rent 返回不同实例
var bullet1 = pool.Rent(); // 独立实例
var bullet2 = pool.Rent(); // 另一个独立实例
// bullet1 != bullet2 → true（不同对象）



                  混淆享元与对象池是最常见的错误 



享元共享同一对象（1 个对象被 N 处引用），对象池复用独立实例（N 个对象轮流使用）。享元解决内存问题，对象池解决 GC 问题。两者经常组合使用，但绝不能混为一谈。


