patterns-设计模式/mediator-pattern-中介者.content:
中介者（Mediator）
核心思想
减少对象之间混乱的直接依赖，迫使它们通过一个中介者对象通信。将多对多（M:N）的网状交互变为星形——所有对象只与中介者通信，互不引用。
结构图
classDiagram
    class IMediator {
        &lt;&lt;interface&gt;&gt;
        +Notify(sender: object, event: string) void
    }
    class ConcreteMediator {
        -_colleagueA: ColleagueA
        -_colleagueB: ColleagueB
        -_colleagueC: ColleagueC
        +Notify(sender: object, event: string) void
    }
    class Colleague {
        &lt;&lt;abstract&gt;&gt;
        #_mediator: IMediator
        +SetMediator(mediator: IMediator)
    }
    class ColleagueA {
        +DoA()
        +ReceiveA()
    }
    class ColleagueB {
        +DoB()
        +ReceiveB()
    }
    class ColleagueC {
        +DoC()
        +ReceiveC()
    }

    IMediator &lt;|.. ConcreteMediator
    Colleague &lt;|-- ColleagueA
    Colleague &lt;|-- ColleagueB
    Colleague &lt;|-- ColleagueC
    Colleague --&gt; IMediator : _mediator
    ConcreteMediator --&gt; ColleagueA : 协调
    ConcreteMediator --&gt; ColleagueB : 协调
    ConcreteMediator --&gt; ColleagueC : 协调

graph TB
    subgraph NoMediator[&quot;没有中介者：M:N 网状依赖&quot;]
        A1[面板A] --- B1[面板B]
        A1 --- C1[系统C]
        B1 --- C1
        A1 --- D1[系统D]
        B1 --- D1
        C1 --- D1
    end

    subgraph WithMediator[&quot;有中介者：星形依赖&quot;]
        A2[面板A] --&gt; M[中介者]
        B2[面板B] --&gt; M
        C2[系统C] --&gt; M
        D2[系统D] --&gt; M
    end

问题动机
没有中介者时，有交互需求的对象之间形成网状依赖：
// 反面教材：UI 面板之间互相引用
public class HUDPanel : MonoBehaviour
{
    public InventoryPanel Inventory;    // 直接引用
    public EquipmentPanel Equipment;    // 直接引用
    public StatsPanel Stats;           // 直接引用
    public SkillPanel Skills;          // 直接引用

    public void OnItemUsed(Item item)
    {
        Inventory.RemoveItem(item);         // 通知背包
        Equipment.EquipItem(item);          // 通知装备栏
        Stats.UpdateAttributes(item.Bonus); // 通知属性面板
        Skills.UnlockIfRelated(item);       // 通知技能面板
        // 每新增一个面板，HUDPanel 就要加引用和调用
    }
}

public class EquipmentPanel : MonoBehaviour
{
    public HUDPanel HUD;          // 反向引用
    public StatsPanel Stats;      // 又一个直接引用

    public void OnEquipmentChanged()
    {
        Stats.UpdateAttributes(CalculateBonus());
        HUD.RefreshDisplay();
        // 循环依赖：Equipment ↔ HUD ↔ Stats
    }
}
这种写法的问题：

网状依赖：N 个对象互相引用，依赖数量 = O(N^2)
修改扩散：新增一个面板，所有相关面板都要加引用和调用
循环引用：A 引用 B，B 引用 A，生命周期管理困难
无法独立测试：测试一个面板必须实例化所有相关面板

中介者的核心动机：将 M:N 的网状交互集中到一个协调者，每个同事对象只与中介者通信。
参与者






























角色职责Unity/C# 对应IMediator声明同事对象通信接口IGameMediator、IUIManager 接口ConcreteMediator实现同事对象间的协调逻辑GameMediator、UIMediatorColleague持有中介者引用，通过中介者通信UI 面板、游戏系统Client创建中介者和同事对象，组装关系场景初始化代码
工作原理
基础实现：游戏系统协调器
public interface IGameMediator
{
    void Notify(object sender, string eventType, object data = null);
}

public class GameMediator : IGameMediator
{
    private readonly HUDPanel _hud;
    private readonly ScoreSystem _score;
    private readonly AudioSystem _audio;
    private readonly AchievementSystem _achievement;

    public GameMediator(HUDPanel hud, ScoreSystem score, AudioSystem audio, AchievementSystem achievement)
    {
        _hud = hud;
        _score = score;
        _audio = audio;
        _achievement = achievement;
    }

    public void Notify(object sender, string eventType, object data)
    {
        switch (eventType)
        {
            case &quot;EnemyKilled&quot;:
                _score.Add(100);
                _hud.UpdateScore(_score.Current);
                _audio.PlaySFX(&quot;kill&quot;);
                _achievement.CheckKill((EnemyData)data);
                break;
            case &quot;PlayerHit&quot;:
                _hud.FlashDamage();
                _audio.PlaySFX(&quot;hit&quot;);
                break;
            case &quot;ItemPickedUp&quot;:
                _hud.ShowPickupMessage((ItemData)data);
                _audio.PlaySFX(&quot;pickup&quot;);
                break;
        }
    }
}

// 同事对象：只与中介者通信
public class Enemy : MonoBehaviour
{
    private IGameMediator _mediator;
    public void Initialize(IGameMediator mediator) =&gt; _mediator = mediator;
    public void Die() =&gt; _mediator.Notify(this, &quot;EnemyKilled&quot;, GetData());
}
类型安全的中介者（替代字符串事件）
用枚举或泛型替代 string eventType，避免拼写错误：
// 枚举事件类型
public enum GameEvent { EnemyKilled, PlayerHit, ItemPickedUp, LevelCompleted }

public interface IGameMediator
{
    void Notify(object sender, GameEvent eventType, object data = null);
}

// 泛型事件类型（更类型安全）
public interface ITypedMediator
{
    void Publish&lt;TEvent&gt;(TEvent evt) where TEvent : struct;
    void Subscribe&lt;TEvent&gt;(Action&lt;TEvent&gt; handler) where TEvent : struct;
}

public class EventMediator : ITypedMediator
{
    private readonly Dictionary&lt;Type, Delegate&gt; _handlers = new();

    public void Subscribe&lt;TEvent&gt;(Action&lt;TEvent&gt; handler) where TEvent : struct
    {
        var type = typeof(TEvent);
        if (_handlers.TryGetValue(type, out var existing))
            _handlers[type] = Delegate.Combine(existing, handler);
        else
            _handlers[type] = handler;
    }

    public void Publish&lt;TEvent&gt;(TEvent evt) where TEvent : struct
    {
        if (_handlers.TryGetValue(typeof(TEvent), out var handler))
            ((Action&lt;TEvent&gt;)handler).Invoke(evt);
    }
}

// 定义事件结构体
public readonly struct EnemyKilledEvent { public readonly int Score; public readonly EnemyType Type; }
public readonly struct PlayerHitEvent { public readonly int Damage; }

// 使用
mediator.Subscribe&lt;EnemyKilledEvent&gt;(e =&gt; AddScore(e.Score));
mediator.Publish(new EnemyKilledEvent { Score = 100, Type = EnemyType.Boss });
游戏开发深度
UI 面板间通信
Unity UI 最典型的中介者应用——面板之间不互相引用，通过中介者联动：
// UI 中介者：管理面板间联动
public class UIMediator : MonoBehaviour
{
    [SerializeField] private InventoryPanel _inventory;
    [SerializeField] private EquipmentPanel _equipment;
    [SerializeField] private StatsPanel _stats;
    [SerializeField] private DetailPanel _detail;

    private void Awake()
    {
        // 所有面板注册到中介者
        _inventory.Initialize(this);
        _equipment.Initialize(this);
        _stats.Initialize(this);
        _detail.Initialize(this);
    }

    public void OnItemSelected(Item item)
    {
        _detail.ShowItemDetail(item);        // 详情面板显示
        _stats.PreviewEquipEffect(item);     // 属性面板预览
    }

    public void OnItemEquipped(Item item)
    {
        _inventory.RemoveItem(item);
        _equipment.EquipItem(item);
        _stats.ApplyEquipEffect(item.Bonus);
    }
}



                  面板不需要知道其他面板的存在 



InventoryPanel 只调用 _mediator.OnItemSelected(item)，不知道谁会响应。新增面板只需在中介者中添加逻辑，现有面板无需修改。


避免 GameManager 变上帝类
游戏开发中常见的反模式：一个 GameManager 管所有事情。中介者模式要求按职责拆分中介者：
// 反面：上帝类 GameManager
public class GameManager : MonoBehaviour
{
    // 几十个系统引用，几千行代码...
    public HUDPanel HUD;
    public ScoreSystem Score;
    public AudioSystem Audio;
    public LevelSystem Level;
    public SaveSystem Save;
    public NetworkManager Network;
    // ...
}

// 正面：按职责拆分中介者
public class CombatMediator : MonoBehaviour { /* 战斗相关 */ }
public class UIMediator : MonoBehaviour { /* UI 联动 */ }
public class ProgressionMediator : MonoBehaviour { /* 升级/成就 */ }
EventBus 作为中介者的轻量变体
EventBus 是中介者的分布式变体——没有集中的 ConcreteMediator，事件通过总线路由：
// EventBus：解耦更彻底，但调试更难
public static class EventBus
{
    private static readonly Dictionary&lt;Type, List&lt;Delegate&gt;&gt; _subscribers = new();

    public static void Subscribe&lt;T&gt;(Action&lt;T&gt; handler)
    {
        var type = typeof(T);
        if (!_subscribers.ContainsKey(type)) _subscribers[type] = new List&lt;Delegate&gt;();
        _subscribers[type].Add(handler);
    }

    public static void Publish&lt;T&gt;(T evt)
    {
        if (!_subscribers.TryGetValue(typeof(T), out var handlers)) return;
        foreach (var handler in handlers)
            ((Action&lt;T&gt;)handler)(evt);
    }

    public static void Clear() =&gt; _subscribers.Clear();
}

// 同事对象不再需要中介者引用
public class Enemy : MonoBehaviour
{
    public void Die() =&gt; EventBus.Publish(new EnemyKilledEvent { Score = 100 });
}

public class ScoreSystem : MonoBehaviour
{
    private void OnEnable() =&gt; EventBus.Subscribe&lt;EnemyKilledEvent&gt;(OnEnemyKilled);
    private void OnDisable() =&gt; EventBus.Unsubscribe&lt;EnemyKilledEvent&gt;(OnEnemyKilled);
    private void OnEnemyKilled(EnemyKilledEvent evt) =&gt; AddScore(evt.Score);
}
与 observer-pattern-观察者 的关系






























维度观察者中介者通信方向一对多（主题→观察者）多对多（同事↔中介者↔同事）谁知道谁主题知道观察者（但不知道具体类型）同事只知道中介者协调逻辑无（主题只管通知）有（中介者决定如何协调）典型场景事件广播系统间联动



                  中介者 = 观察者 + 协调逻辑 



中介者内部通常用观察者机制实现通信，但增加了”收到事件后该怎么协调”的逻辑。观察者是”发通知”，中介者是”收通知并协调”。


变体与演进



































变体特点适用场景复杂度集中式中介者一个类知道所有同事，协调逻辑集中同事少、交互逻辑明确低EventBus全局事件路由，发布者/订阅者互不知道跨系统通信、同事多中C# event 作为轻量中介者用静态事件替代中介者类简单通信、不需要协调逻辑极低消息队列异步解耦，事件入队后延迟处理时序敏感、需要回放高
// C# event 作为轻量中介者
public static class GameEvents
{
    public static event Action&lt;EnemyKilledEvent&gt; OnEnemyKilled;
    public static event Action&lt;PlayerHitEvent&gt; OnPlayerHit;

    public static void Publish&lt;T&gt;(T evt)
    {
        if (evt is EnemyKilledEvent e) OnEnemyKilled?.Invoke(e);
        else if (evt is PlayerHitEvent p) OnPlayerHit?.Invoke(p);
    }
}

// 与 EventBus 的区别：没有路由逻辑，只是事件的多播委托
反模式



                  中介者变成&quot;上帝对象&quot; 



所有交互逻辑集中到一个中介者，它变得比原来的网状依赖更难维护。判断标准：如果中介者超过 300 行或引用了超过 5 个同事，考虑拆分。按职责域拆分多个中介者（如 CombatMediator、UIMediator、ProgressionMediator）。





                  中介者知道太多同事细节 



如果中介者直接调用同事的内部方法（如 _inventory._scrollRect.verticalNormalizedPosition = 0），说明中介者和同事的耦合度太高。同事应提供高层接口（如 _inventory.ResetScroll()），中介者只调用高层接口。





                  用 EventBus 替代所有通信 



“所有事件都走 EventBus”会导致：事件名冲突、调试时无法追踪事件来源和去向、隐式依赖遍布代码。EventBus 适合跨层级通信（如 UI 与游戏逻辑），同层通信用直接调用或观察者更清晰。参见 observer-pattern-观察者。


权衡与选择

用中介者：多个对象之间有复杂交互、需要集中协调时
用观察者：只需一对多通知、不需要协调逻辑时（更轻量）
用外观：只需简化接口、不需要对象间双向通信时
用责任链：请求需要沿链顺序处理时
用命令：通信内容需要被封装、排队或撤销时

相关

design-patterns-设计模式 — 设计模式总览
behavioral-patterns-行为型 — 行为型模式
observer-pattern-观察者 — 观察者：一对多通知（中介者的通信基础）
facade-pattern-外观 — 外观：简化接口（单向简化 vs 双向协调）
command-pattern-命令 — 命令：封装通信为对象
singleton-pattern-单例 — 单例：中介者常被实现为单例（但应避免）
chain-of-responsibility-责任链 — 责任链：链式处理 vs 集中协调
event-queue-事件队列 — 事件队列：异步中介者变体

patterns-设计模式/memento-pattern-备忘录.content:
备忘录（Memento）
核心思想
在不暴露对象实现细节的情况下保存和恢复对象之前的状态。将状态的快照封装为独立对象——原发器的内部状态被备忘录”冻结”，外部只能传递不能读取细节。
结构图
classDiagram
    class Originator {
        -_state: State
        +Save() Memento
        +Restore(memento: Memento)
        +DoSomething()
    }
    class Memento {
        -_state: State
        -_timestamp: DateTime
        +GetState() State
        +GetName() string
    }
    class Caretaker {
        -_history: Stack~Memento~
        -_maxHistory: int
        +Push(memento: Memento)
        +Pop() Memento
        +Clear()
    }

    Originator --&gt; Memento : 创建/消费
    Caretaker --&gt; Memento : 存储（不读取内容）
    note for Caretaker &quot;只负责存储和传递备忘录，不读取其内部状态&quot;

sequenceDiagram
    participant Client
    participant Originator
    participant Caretaker
    participant Memento

    Note over Client: 保存状态
    Client-&gt;&gt;Originator: Save()
    Originator-&gt;&gt;Memento: new Memento(state)
    Originator--&gt;&gt;Client: memento
    Client-&gt;&gt;Caretaker: Push(memento)

    Note over Client: 修改状态
    Client-&gt;&gt;Originator: DoSomething()
    Note over Originator: 状态已改变

    Note over Client: 撤销
    Client-&gt;&gt;Caretaker: Pop()
    Caretaker--&gt;&gt;Client: memento
    Client-&gt;&gt;Originator: Restore(memento)
    Originator-&gt;&gt;Memento: GetState()
    Note over Originator: 状态已恢复

问题动机
没有备忘录时，保存/恢复对象状态要么暴露内部实现，要么违反封装：
// 反面教材 1：直接暴露内部状态进行保存/恢复
public class Player : MonoBehaviour
{
    public Vector3 Position;  // 被迫 public
    public int Hp;            // 被迫 public
    public int Score;         // 被迫 public
    public float Stamina;     // 被迫 public
    public List&lt;Buff&gt; Buffs;  // 被迫 public，且是引用类型！

    // 保存逻辑散落在各处
    public PlayerSaveData Save()
    {
        return new PlayerSaveData
        {
            Position = Position,   // 外部可以直接修改 Position
            Hp = Hp,               // 破坏封装
            Score = Score,
            Stamina = Stamina,
            Buffs = new List&lt;Buff&gt;(Buffs) // 容易忘记深拷贝
        };
    }
}

// 反面教材 2：保存逻辑与业务逻辑混杂
public class Player : MonoBehaviour
{
    private Vector3 _position;
    private int _hp;

    // 业务方法里夹杂保存逻辑
    public void TakeDamage(int damage)
    {
        _lastHp = _hp;  // 保存前一个状态？还是前两个？
        _hp -= damage;
        if (_hp &lt;= 0) { /* 死亡逻辑 */ }
    }

    // 多步撤销需要多个临时变量
    private int _lastHp;
    private int _lastLastHp;
    private Vector3 _lastPosition;
    // 每加一个字段，撤销逻辑指数级膨胀
}
这种写法的问题：

封装破裂：为了保存状态，把所有字段暴露为 public
保存逻辑散落：每个修改状态的地方都要手动保存前一个值
深拷贝陷阱：引用类型（List&lt;Buff&gt;）容易忘记深拷贝，恢复后指向同一对象
多步撤销困难：手动管理 _lastXxx 变量，字段越多越混乱

备忘录的核心动机：让对象自己负责保存/恢复状态，外部只传递备忘录不解读其内容——既保存了完整状态，又不违反封装。
参与者

























角色职责Unity/C# 对应Originator（原发器）创建备忘录（保存状态）和用备忘录恢复状态Player、LevelEditor、GameStateMemento（备忘录）封装 Originator 的内部状态快照PlayerMemento、SaveData 序列化对象Caretaker（负责人）存储备忘录历史，不读取其内容SaveManager、UndoHistory、CheckPointManager



                  Caretaker 的&quot;不读取&quot;原则 



GoF 强调 Caretaker 只负责存储和传递备忘录，不读取或操作备忘录的内部状态。在 C# 中这个约束靠约定（而非语言强制），备忘录类可以把状态字段设为 internal 或 private，只对 Originator 所在程序集可见。


工作原理
基础实现
// 备忘录：保存的状态快照（不可变）
public class PlayerMemento
{
    public Vector3 Position { get; }
    public int Hp { get; }
    public int Score { get; }
    public float Stamina { get; }
    public DateTime Timestamp { get; }

    public PlayerMemento(Vector3 pos, int hp, int score, float stamina)
    {
        Position = pos;
        Hp = hp;
        Score = score;
        Stamina = stamina;
        Timestamp = DateTime.Now;
    }
}

// 原发器：需要保存/恢复状态的对象
public class Player : MonoBehaviour
{
    public Vector3 Position { get; set; }
    public int Hp { get; set; }
    public int Score { get; set; }
    public float Stamina { get; set; }

    public PlayerMemento Save() =&gt; new(Position, Hp, Score, Stamina);

    public void Restore(PlayerMemento memento)
    {
        Position = memento.Position;
        Hp = memento.Hp;
        Score = memento.Score;
        Stamina = memento.Stamina;
    }
}

// 负责人：管理备忘录历史
public class SaveManager
{
    private readonly Stack&lt;PlayerMemento&gt; _history = new();
    private readonly int _maxHistory;

    public SaveManager(int maxHistory = 50) =&gt; _maxHistory = maxHistory;

    public void Save(Player player)
    {
        if (_history.Count &gt;= _maxHistory)
            TrimHistory(); // 超出上限时压缩旧快照
        _history.Push(player.Save());
    }

    public void Undo(Player player)
    {
        if (_history.Count &gt; 0)
            player.Restore(_history.Pop());
    }

    private void TrimHistory()
    {
        // 保留最近的一半快照
        var recent = new Stack&lt;PlayerMemento&gt;();
        int keep = _maxHistory / 2;
        for (int i = 0; i &lt; keep; i++)
            recent.Push(_history.Pop());
        _history.Clear();
        foreach (var m in recent.Reverse())
            _history.Push(m);
    }
}
泛型备忘录管理器
// 泛型备忘录：让任何 Originator 都能保存/恢复
public interface IOriginator&lt;TState&gt;
{
    TState CaptureState();
    void RestoreState(TState state);
}

public class HistoryManager&lt;TState&gt;
{
    private readonly Stack&lt;TState&gt; _history = new();
    private readonly int _maxDepth;
    private readonly Action&lt;TState&gt; _onDiscard; // 快照被丢弃时的回调

    public HistoryManager(int maxDepth = 50, Action&lt;TState&gt; onDiscard = null)
    {
        _maxDepth = maxDepth;
        _onDiscard = onDiscard;
    }

    public void Save(IOriginator&lt;TState&gt; originator)
    {
        if (_history.Count &gt;= _maxDepth)
        {
            var oldest = _history.Pop();
            _onDiscard?.Invoke(oldest);
        }
        _history.Push(originator.CaptureState());
    }

    public bool Undo(IOriginator&lt;TState&gt; originator)
    {
        if (_history.Count == 0) return false;
        originator.RestoreState(_history.Pop());
        return true;
    }

    public void Clear() =&gt; _history.Clear();
}
游戏开发深度
关卡编辑器撤销系统（与 Command 配合）
关卡编辑器中，撤销需要同时记录”做了什么”（命令）和”之前的状态”（备忘录）：
// 编辑器操作 = 命令 + 备忘录
public class EditorCommand
{
    public string Description;
    public IEditorAction Action;      // 正向操作
    public EditorSnapshot Before;     // 备忘录：操作前的状态
    // After 快照可选——某些操作可以用 Action 的逆操作恢复
}

public class EditorHistory
{
    private readonly Stack&lt;EditorCommand&gt; _undoStack = new();
    private readonly Stack&lt;EditorCommand&gt; _redoStack = new();

    public void Execute(EditorCommand cmd)
    {
        cmd.Action.Execute();
        _undoStack.Push(cmd);
        _redoStack.Clear();
    }

    public void Undo()
    {
        if (_undoStack.Count == 0) return;
        var cmd = _undoStack.Pop();
        // 优先用备忘录恢复，其次用逆操作
        if (cmd.Before != null)
            cmd.Before.Restore();
        else
            cmd.Action.Undo();
        _redoStack.Push(cmd);
    }

    public void Redo()
    {
        if (_redoStack.Count == 0) return;
        var cmd = _redoStack.Pop();
        cmd.Action.Execute();
        _undoStack.Push(cmd);
    }
}



                  命令 vs 备忘录：谁负责撤销 



command-pattern-命令 记录”做了什么”，用逆操作撤销（如”移动”的反操作是”移回”）。备忘录记录”之前的状态”，直接恢复。选择依据：逆操作简单用命令，状态复杂或逆操作困难用备忘录。复杂编辑器通常两者配合使用。


游戏存档/读档
游戏存档是备忘录模式的最大规模应用——整个游戏世界状态被冻结为可序列化的快照：
[Serializable]
public class GameSaveData
{
    public string SceneName;
    public PlayerSaveData Player;
    public List&lt;EnemySaveData&gt; Enemies;
    public List&lt;ItemSaveData&gt; WorldItems;
    public Dictionary&lt;string, bool&gt; Flags;  // 剧情标记
    public float PlayTime;
}

public class SaveSystem
{
    private const string SavePath = &quot;saves/&quot;;

    public void Save(GameSaveData data, int slot)
    {
        var json = JsonUtility.ToJson(data, prettyPrint: true);
        var path = Path.Combine(Application.persistentDataPath, SavePath, $&quot;slot_{slot}.sav&quot;);
        File.WriteAllText(path, json);
    }

    public GameSaveData Load(int slot)
    {
        var path = Path.Combine(Application.persistentDataPath, SavePath, $&quot;slot_{slot}.sav&quot;);
        if (!File.Exists(path)) return null;
        var json = File.ReadAllText(path);
        return JsonUtility.FromJson&lt;GameSaveData&gt;(json);
    }
}
序列化陷阱（JSON/二进制选择）



































序列化方式优点缺点适用场景JsonUtility轻量、Unity 内置、可读不支持 Dictionary、多态简单存档、配置Newtonsoft.Json功能完整、支持多态较重、GC 压力复杂存档二进制（BinaryWriter）快速、紧凑不可读、版本迁移困难网络快照、回放ScriptableObjectInspector 可编辑运行时修改不持久配置数据（非存档）
// JsonUtility 的多态陷阱
[Serializable]
public class SaveData
{
    public ItemData[] Items; // JsonUtility 无法正确序列化 ItemData 的子类！
}

// 解决方案 1：用 [SerializeReference]（Unity 2020.3+）
[Serializable]
public class SaveData
{
    [SerializeReference]
    public IItemData[] Items; // 支持多态序列化
}

// 解决方案 2：手动类型分发
[Serializable]
public class ItemData
{
    public string Type; // &quot;Weapon&quot;, &quot;Armor&quot;, &quot;Potion&quot;
    public string Json; // 各类型的 JSON 子串
}



                  JsonUtility 的限制 



JsonUtility.ToJson() 不支持 Dictionary、不支持多态（子类字段丢失）、不支持 null 数组元素。复杂存档建议用 Newtonsoft.Json（Unity 2020+ 已内置 com.unity.nuget.newtonsoft-json）。


检查点系统
检查点是有限深度的备忘录栈——只保留关键节点的快照：
public class CheckpointSystem : MonoBehaviour
{
    private readonly List&lt;(string id, GameSaveData snapshot)&gt; _checkpoints = new();
    private const int MaxCheckpoints = 10;

    public void CreateCheckpoint(string id)
    {
        var snapshot = CaptureWorldState();
        _checkpoints.Add((id, snapshot));
        if (_checkpoints.Count &gt; MaxCheckpoints)
            _checkpoints.RemoveAt(0); // 丢弃最旧的检查点
    }

    public bool RestoreCheckpoint(string id)
    {
        var cp = _checkpoints.FindLast(c =&gt; c.id == id);
        if (cp.snapshot == null) return false;
        RestoreWorldState(cp.snapshot);
        return true;
    }
}
变体与演进



































变体特点适用场景内存开销完整快照每次保存全部状态状态小、保存频率低高增量备忘录只记录与前一个快照的差异状态大、保存频繁低命令 + 备忘录命令记录操作，备忘录记录关键节点状态编辑器撤销中序列化备忘录用 JSON/二进制序列化替代手写备忘录类存档系统视格式
增量备忘录
// 增量备忘录：只存差异
public class IncrementalMemento
{
    public Dictionary&lt;string, object&gt; ChangedFields { get; } = new();
    public int BaseSnapshotIndex { get; }
}

public class IncrementalHistory
{
    private readonly List&lt;object&gt; _fullSnapshots = new();        // 完整快照（稀疏）
    private readonly List&lt;IncrementalMemento&gt; _deltas = new(); // 增量差异

    public void Save(object state)
    {
        if (_fullSnapshots.Count == 0 || _deltas.Count &gt;= 10)
        {
            // 每 10 次存一个完整快照
            _fullSnapshots.Add(state);
            _deltas.Clear();
        }
        else
        {
            // 存差异
            var delta = ComputeDelta(_fullSnapshots[^1], state);
            _deltas.Add(delta);
        }
    }
}



                  增量备忘录的权衡 



增量快照节省内存，但恢复时需要从最近完整快照开始依次应用差异——恢复速度较慢。适合”保存频繁、恢复较少”的场景（如自动存档）。


用序列化实现备忘录
当状态结构复杂时，用序列化替代手写备忘录类：
// 用 JSON 序列化作为备忘录——状态类就是备忘录
[Serializable]
public class GameState
{
    public int Level;
    public float PlayerHp;
    public int Score;
    // 所有需要保存的字段...
}

public class GameOriginator
{
    private GameState _state = new();

    // 备忘录 = JSON 字符串
    public string Save() =&gt; JsonUtility.ToJson(_state);
    public void Restore(string memento) =&gt; JsonUtility.FromJsonOverwrite(memento, _state);
}

// Caretaker
public class GameHistory
{
    private readonly Stack&lt;string&gt; _jsonSnapshots = new();
    public void Save(GameOriginator originator) =&gt; _jsonSnapshots.Push(originator.Save());
    public void Undo(GameOriginator originator) =&gt; originator.Restore(_jsonSnapshots.Pop());
}
反模式



                  备忘录泄漏内存（Caretaker 无限保留历史） 



每个备忘录持有完整状态快照，如果 Caretaker 的栈没有深度限制，长时间运行会持续消耗内存。必须设置历史深度上限，超出时丢弃最旧的快照或改用增量备忘录。编辑器工具中尤其容易忽视——用户可能连续撤销 1000 次。





                  备忘录暴露内部实现 



如果备忘录类用 public 字段，任何代码都能读取或修改备忘录内容——这违反了备忘录的封装意图。备忘录的状态应设为 internal 或 private，仅 Originator 能访问。在 C# 中可用 internal 访问修饰符 + [InternalsVisibleTo] 控制。





                  引用类型的浅拷贝陷阱 



备忘录中的引用类型（List&lt;T&gt;、自定义类）如果只拷贝引用而非深拷贝，恢复时两个备忘录会指向同一个对象——修改一个会影响所有快照：
// 错误：浅拷贝
public PlayerMemento(List&lt;Buff&gt; buffs) { Buffs = buffs; } // 同一个 List！

// 正确：深拷贝
public PlayerMemento(List&lt;Buff&gt; buffs) { Buffs = new List&lt;Buff&gt;(buffs); }
对嵌套引用类型需要递归深拷贝，或使用序列化（JsonUtility.ToJson → FromJson）实现深拷贝。


权衡与选择

用备忘录：需要完整状态快照、撤销时直接恢复时
用命令：只需撤销操作（而非完整回滚状态）时——参见 command-pattern-命令
用序列化：存档系统通常直接用 JsonUtility/BinaryFormatter，本质是备忘录的特化
用原型：需要克隆对象整体（而非仅状态快照）时——参见 prototype-pattern-原型
备忘录 + 命令：编辑器撤销——命令记录”做了什么”，备忘录记录”之前的状态”

