对象池（Object Pool）
核心思想
预创建一组对象并重复使用，避免频繁的实例化和销毁。取用时从池中获取，用完归还池中——对象被循环利用而非创建后丢弃。本质是用空间换时间：常驻内存避免 GC 开销，在”内存常驻”与”分配/回收代价”之间取舍。

GPP 关键洞察：对象池解决了游戏开发中最常见的性能陷阱——频繁 new 和 destroy 导致 GC Spike。Nystrom 的核心论点：如果你的对象”用完即弃”但类型固定、大小固定，就不应该真的”丢弃”——复用才是正解。

结构图
classDiagram
    class ObjectPool~T~ {
        -_available: Stack~T~
        -_active: HashSet~T~
        -_createFunc: Func~T~
        -_maxSize: int
        +Get() T
        +Release(obj: T)
        +CountActive: int
        +CountInactive: int
    }

    class IPoolable {
        &lt;&lt;interface&gt;&gt;
        +OnGet()
        +OnRelease()
    }

    class Bullet {
        +Position: Vector3
        +Direction: Vector3
        +Speed: float
        +IsActive: bool
        +OnGet()
        +OnRelease()
        +Reset()
    }

    class Client {
        -_pool: ObjectPool~Bullet~
        +FireBullet()
        +OnBulletHit()
    }

    ObjectPool --&gt; IPoolable : 管理
    IPoolable &lt;|.. Bullet
    Client --&gt; ObjectPool : Get / Release
    ObjectPool o-- Bullet : 持有可用实例栈

问题动机
反面教材：每帧 Instantiate+Destroy
不用对象池会怎样？子弹/特效频繁 new 和 destroy 导致 GC Spike：
// 反面教材：每帧 Instantiate+Destroy 导致 GC Spike
public class BulletManager : MonoBehaviour
{
    public GameObject BulletPrefab;

    public void Fire(Vector3 pos, Vector3 dir)
    {
        // 每次射击：Instantiate = 堆分配 + 初始化
        var bullet = Instantiate(BulletPrefab, pos, Quaternion.LookRotation(dir));
        // 子弹命中或飞出屏幕后 Destroy
        // Destroy → GC 回收 → 内存碎片 → 下次分配更慢
    }

    private void Update()
    {
        // 100 发/秒 = 100 次 Instantiate + 100 次 Destroy/秒
        // = 100 次堆分配 + 100 次 GC 回收/秒
        // = GC Spike（帧率卡顿）
    }
}

// 问题 1：Instantiate 内部做堆分配（new GameObject → 多个组件分配）
// 问题 2：Destroy 不立即释放内存，等 GC 回收 → 不可控的卡顿
// 问题 3：频繁分配/回收导致堆碎片化 → 大对象分配更慢
// 问题 4：GC 每次扫描都要遍历所有堆对象 → 对象越多扫描越慢
// 正面做法：复用子弹实例
public class BulletManager : MonoBehaviour
{
    private ObjectPool&lt;Bullet&gt; _pool;

    public void Fire(Vector3 pos, Vector3 dir)
    {
        var bullet = _pool.Get(); // 从池中取，无分配
        bullet.Launch(pos, dir);
    }

    public void OnBulletHit(Bullet bullet)
    {
        bullet.OnHit();
        _pool.Release(bullet); // 归还池中，无 Destroy
    }
    // 全程零堆分配、零 GC、零卡顿
}
参与者






























角色职责Unity/C# 对应对象池管理对象的获取、归还和生命周期UnityEngine.Pool.ObjectPool&lt;T&gt;池化对象接口定义对象获取/归还时的行为IPoolable（自定义）、OnGet/OnRelease客户端从池中取对象、用完归还子弹系统、特效系统、音效系统工厂函数池为空时创建新对象Func&lt;T&gt;、Instantiate



                  对象池 vs 享元模式——关键区分 



两者都涉及”复用”，但本质不同——对象池复用实例（同一对象在不同时间被不同调用者使用），享元复用数据（多个对象共享同一份不可变数据）。子弹池是对象池（每颗子弹有独立的位置/方向），材质共享是享元（多个渲染器共享同一个 Material）。参见 flyweight-pattern-享元。


游戏开发深度
最简实现：List&lt;GameObject&gt;（手动池）
Unity 2021 之前或极简场景，可用 List&lt;GameObject&gt; 手写池：
public class SimpleObjectPool
{
    private GameObject _prefab;
    private readonly List&lt;GameObject&gt; _list = new();

    public void CreateObject(GameObject prefab, int count = 1)
    {
        _prefab = prefab;
        for (int i = 0; i &lt; count; i++)
        {
            var obj = Object.Instantiate(prefab);
            obj.SetActive(false);
            _list.Add(obj);
        }
    }

    public GameObject Get()
    {
        if (_list.Count &gt; 0)
        {
            var obj = _list[0];
            _list.RemoveAt(0);
            obj.SetActive(true);
            return obj;
        }
        return Object.Instantiate(_prefab); // 池空则创建新对象
    }

    public void Put(GameObject obj)
    {
        obj.SetActive(false);
        _list.Add(obj);
    }
}



                  何时用 SimpleObjectPool vs Unity ObjectPool&lt;T&gt; 



SimpleObjectPool 适合快速原型或极简项目。生产代码建议用 Unity 官方 ObjectPool&lt;T&gt;——它提供 collectionCheck（防重复释放）、maxSize（防内存膨胀）、onGet/onRelease/onDestroy 回调。


Unity 的 ObjectPool&lt;T&gt;（Unity 2021+）——官方 API
Unity 2021+ 提供了 UnityEngine.Pool.ObjectPool&lt;T&gt;：
// Unity 官方对象池 API
using UnityEngine.Pool;

public class BulletPoolExample : MonoBehaviour
{
    [SerializeField] private GameObject _bulletPrefab;
    private ObjectPool&lt;GameObject&gt; _pool;

    private void Awake()
    {
        _pool = new ObjectPool&lt;GameObject&gt;(
            createFunc: () =&gt; Instantiate(_bulletPrefab),
            onGet: obj =&gt; obj.SetActive(true),
            onRelease: obj =&gt; obj.SetActive(false),
            onDestroy: obj =&gt; Destroy(obj),
            collectionCheck: true, // 释放时检查是否重复释放
            defaultCapacity: 50,
            maxSize: 200
        );
    }

    public void Fire(Vector3 pos, Vector3 dir)
    {
        var bullet = _pool.Get();
        bullet.transform.position = pos;
        bullet.transform.rotation = Quaternion.LookRotation(dir);
    }

    public void ReturnBullet(GameObject bullet) =&gt; _pool.Release(bullet);
}



                  Unity ObjectPool 的 collectionCheck 



collectionCheck: true 时，Release 会检查对象是否已在池中（防止重复释放）。开发阶段开启，发布阶段关闭（避免额外 HashSet 查找开销）。


UnityEngine.Pool 命名空间详解
Unity 2021+ 的 UnityEngine.Pool 命名空间提供了多种池化工具：





























类用途ObjectPool&lt;T&gt;通用对象池，支持自定义创建/获取/释放/销毁回调LinkedPool&lt;T&gt;链表实现的池，内存开销更低DictionaryPool&lt;TKey, TValue&gt;Dictionary 的池化版本，避免每次 new DictionaryListPool&lt;T&gt;List 的池化版本，适合临时列表GenericPool&lt;T&gt;自动创建实例的泛型池
// ListPool：避免临时列表的 GC
public class CollisionSystem : MonoBehaviour
{
    private void Update()
    {
        // 从池中获取 List，用完归还
        var results = ListPool&lt;Collider&gt;.Get();
        try
        {
            Physics.OverlapSphereNonAlloc(transform.position, 10f, results.ToArray());
            // 处理碰撞...
        }
        finally
        {
            ListPool&lt;Collider&gt;.Release(results);
        }
    }
}
子弹系统对象池完整示例
// 完整的子弹系统对象池
public class Bullet : MonoBehaviour, IPoolable
{
    public Vector3 Direction;
    public float Speed = 30f;
    public float MaxLifetime = 3f;

    private float _lifetime;
    private BulletPool _pool;

    public void Initialize(BulletPool pool) =&gt; _pool = pool;

    public void Launch(Vector3 pos, Vector3 dir)
    {
        transform.position = pos;
        Direction = dir;
        _lifetime = 0f;
        gameObject.SetActive(true);
    }

    private void Update()
    {
        transform.position += Direction * Speed * Time.deltaTime;
        _lifetime += Time.deltaTime;

        if (_lifetime &gt;= MaxLifetime)
            ReturnToPool();
    }

    private void OnTriggerEnter(Collider other)
    {
        // 命中处理...
        ReturnToPool();
    }

    private void ReturnToPool() =&gt; _pool.Release(this);

    public void OnPoolGet() { /* 对象被取出时的初始化 */ }
    public void OnPoolRelease()
    {
        Direction = Vector3.zero;
        _lifetime = 0f;
        gameObject.SetActive(false);
    }
}

// 子弹池管理器
public class BulletPool : MonoBehaviour
{
    [SerializeField] private Bullet _bulletPrefab;
    [SerializeField] private int _initialSize = 50;

    private Stack&lt;Bullet&gt; _available = new();
    private List&lt;Bullet&gt; _active = new();

    private void Awake()
    {
        for (int i = 0; i &lt; _initialSize; i++)
        {
            var bullet = Instantiate(_bulletPrefab, transform);
            bullet.Initialize(this);
            bullet.gameObject.SetActive(false);
            _available.Push(bullet);
        }
    }

    public Bullet Get(Vector3 pos, Vector3 dir)
    {
        Bullet bullet;
        if (_available.Count &gt; 0)
        {
            bullet = _available.Pop();
        }
        else
        {
            bullet = Instantiate(_bulletPrefab, transform);
            bullet.Initialize(this);
        }

        bullet.Launch(pos, dir);
        _active.Add(bullet);
        return bullet;
    }

    public void Release(Bullet bullet)
    {
        _active.Remove(bullet);
        bullet.OnPoolRelease();
        _available.Push(bullet);
    }
}
特效/音效池化
// 特效池化——粒子系统
public class VFXPool : MonoBehaviour
{
    [SerializeField] private ParticleSystem _vfxPrefab;
    private Stack&lt;ParticleSystem&gt; _available = new();

    public ParticleSystem Play(Vector3 pos, Quaternion rotation)
    {
        var vfx = Get();
        vfx.transform.SetPositionAndRotation(pos, rotation);
        vfx.Play();
        StartCoroutine(ReturnWhenDone(vfx));
        return vfx;
    }

    private IEnumerator ReturnWhenDone(ParticleSystem vfx)
    {
        yield return new WaitWhile(() =&gt; vfx.isPlaying);
        Release(vfx);
    }

    private ParticleSystem Get()
    {
        if (_available.Count &gt; 0)
        {
            var vfx = _available.Pop();
            vfx.gameObject.SetActive(true);
            return vfx;
        }
        return Instantiate(_vfxPrefab, transform);
    }

    private void Release(ParticleSystem vfx)
    {
        vfx.gameObject.SetActive(false);
        _available.Push(vfx);
    }
}

// 音效池化——AudioSource 复用
public class AudioPool : MonoBehaviour
{
    private List&lt;AudioSource&gt; _sources = new();
    private int _poolSize = 10;

    private void Awake()
    {
        for (int i = 0; i &lt; _poolSize; i++)
        {
            var go = new GameObject($&quot;AudioSource_{i}&quot;);
            go.transform.SetParent(transform);
            var source = go.AddComponent&lt;AudioSource&gt;();
            source.playOnAwake = false;
            _sources.Add(source);
        }
    }

    public void PlayClip(AudioClip clip, Vector3 position, float volume = 1f)
    {
        var source = _sources.FirstOrDefault(s =&gt; !s.isPlaying);
        if (source != null)
        {
            source.transform.position = position;
            source.clip = clip;
            source.volume = volume;
            source.Play();
        }
    }
}
与享元模式的区分（关键！）



































维度对象池享元模式复用什么实例（整个对象在不同时间被不同调用者使用）数据（多个对象共享同一份不可变数据）对象状态每次取出时重置为初始状态共享数据始终不变内存模型多个实例独立存在一个实例被多处引用典型例子子弹池、特效池纹理共享、Material 共享时间 vs 空间空间换时间（常驻内存省 GC）空间节省（共享数据减少内存）
// 对象池 + 享元的组合
public class BulletPool
{
    private Stack&lt;Bullet&gt; _pool = new();
    private Sprite _sharedBulletSprite; // 享元——不可变共享数据

    public Bullet Get()
    {
        var bullet = _pool.Count &gt; 0 ? _pool.Pop() : CreateNew();
        bullet.Sprite = _sharedBulletSprite; // 共享享元数据
        bullet.Reset(); // 重置对象状态（非享元部分）
        return bullet;
    }
}
DOTS 中的对象池
在 DOTS/ECS 中，对象池的概念以不同形式存在：
// DOTS 中不直接 &quot;Instantiate/Destroy&quot;，而是创建/销毁 Entity
// Entity 本身是轻量 ID，创建/销毁开销很低
// 真正的开销在 Component 数据分配

// EntityCommandBuffer 延迟创建/销毁 = 类似池化的批量处理
var ecb = new EntityCommandBuffer(Allocator.TempJob);

// 创建：从 Archetype 批量创建（内部有 chunk 复用）
var entity = ecb.CreateEntity(_bulletArchetype);
ecb.SetComponent(entity, new Position { Value = spawnPos });

// 销毁：Entity 只是标记移除，Archetype 的 Chunk 不会立即释放
ecb.DestroyEntity(entity);

// DOTS 的 Chunk 本身有复用机制——类似对象池
// 同一 Archetype 的 Entity 在 Chunk 中连续排列
// Entity 销毁后 Chunk 空间自动复用



                  ECS 的&quot;免费池化&quot; 



ECS 的 Archetype + Chunk 机制天然提供了类似对象池的效果——Entity 销毁后，Chunk 中的空间被下一个同类型 Entity 复用。不需要手动实现对象池。参见 dots-ecs-数据导向。


对象池与 GC 的关系
对象池对 GC 的影响是根本性的——参见 garbage-collection-GC与内存：
// 量化对比（100 发/秒的子弹系统）：
// 无池：100 次 new/秒 + 100 次 Destroy/秒
//   → Gen0 GC 每 ~2 秒触发一次（~2ms 卡顿）
//   → Gen1 GC 每 ~10 秒触发一次（~10ms 卡顿）
// 有池：0 次 new/秒 + 0 次 Destroy/秒
//   → GC 触发频率大幅降低
//   → 池中对象常驻 Gen2，不被回收



                  池化对象对 GC 的影响 



池化对象常驻内存，最终会升到 Gen2。这对 GC 来说是好事——Gen2 对象不会被频繁扫描。但池化太多对象会增大 Gen2 体积，Gen2 GC 触发时扫描更慢。平衡点：只池化真正高频使用的对象。


