变体容量策略优点缺点适用场景固定大小池预创建，不扩容零运行时分配容量不足时无法获取子弹（数量可预测）动态扩容池按需创建，有上限弹性峰值时仍有分配特效（数量不可预测）多类型池按类型分池统一管理每种类型独立上限多种特效/音效带生命周期池超时自动归还防泄漏定时器开销网络连接、临时对象Native 池unmanaged 内存Burst 兼容手动管理 DisposeJob System 中使用
带生命周期的自动回收池
// 自动回收池：忘记归还也不泄漏
public class AutoReturnPool&lt;T&gt; where T : Component
{
    private readonly Stack&lt;T&gt; _available = new();
    private readonly Dictionary&lt;T, float&gt; _activeLifetimes = new();
    private readonly float _maxLifetime;

    public AutoReturnPool(float maxLifetime = 5f) =&gt; _maxLifetime = maxLifetime;

    public T Get()
    {
        var obj = _available.Count &gt; 0 ? _available.Pop() : CreateNew();
        _activeLifetimes[obj] = Time.time + _maxLifetime;
        obj.gameObject.SetActive(true);
        return obj;
    }

    public void Release(T obj)
    {
        _activeLifetimes.Remove(obj);
        obj.gameObject.SetActive(false);
        _available.Push(obj);
    }

    public void Tick()
    {
        float now = Time.time;
        var expired = _activeLifetimes.Where(kvp =&gt; now &gt;= kvp.Value).ToList();
        foreach (var kvp in expired)
            Release(kvp.Key);
    }
}
反模式



                  忘记归还对象——池泄漏 



从池中取出对象后忘记归还，池逐渐枯竭，最后被迫不断创建新对象，等于没有池化。解决：使用 using 模式或自动回收机制。


// 使用 using 模式防止忘记归还
public class PooledObject&lt;T&gt; : IDisposable where T : class
{
    public T Value { get; }
    private readonly ObjectPool&lt;T&gt; _pool;
    private bool _disposed;

    public PooledObject(T value, ObjectPool&lt;T&gt; pool)
    {
        Value = value;
        _pool = pool;
    }

    public void Dispose()
    {
        if (!_disposed)
        {
            _pool.Release(Value);
            _disposed = true;
        }
    }
}



                  池中对象状态未重置 



归还对象时不重置状态，下次取出的对象带着上次的数据——位置错误、碰撞残留、UI 文字残留。每次归还必须完整重置。


// 正确：归还时完整重置
public void ReturnBullet(Bullet bullet)
{
    bullet.transform.position = Vector3.zero;
    bullet.Direction = Vector3.zero;
    bullet.Speed = 0;
    bullet._lifetime = 0;
    bullet.gameObject.SetActive(false);
    _pool.Release(bullet);
}



                  池大小设置不当 




太小：频繁扩容，峰值性能下降
太大：浪费内存，GC 扫描更多对象
经验法则：池大小 = 预估峰值 * 1.2（留 20% 余量），用 Profiler 确认实际峰值



