问题动机
反面教材：双层 for 循环 O(n^2) 碰撞
不用空间分区会怎样？暴力碰撞检测——每个对象与所有其他对象检查碰撞：
// 反面教材：暴力碰撞检测 O(n^2)
public class CollisionSystem
{
    private List&lt;Enemy&gt; _enemies = new();

    private void Update()
    {
        // 双层循环：每个敌人与所有其他敌人检查碰撞
        for (int i = 0; i &lt; _enemies.Count; i++)
        {
            for (int j = i + 1; j &lt; _enemies.Count; j++)
            {
                // 1000 个敌人 = 499,500 次距离计算
                // 其中 99% 的对距离很远，根本不可能碰撞
                float dist = Vector3.Distance(
                    _enemies[i].Position,
                    _enemies[j].Position);
                if (dist &lt; _enemies[i].Radius + _enemies[j].Radius)
                {
                    ResolveCollision(_enemies[i], _enemies[j]);
                }
            }
        }
    }
}

// 问题 1：O(n^2) 复杂度——1000 个对象要检查 ~500,000 对
// 问题 2：左上角的对象与右下角的对象距离 1000 米也在检查
// 问题 3：对象数翻倍，检查量翻四倍——不可扩展
// 正面做法：只检查邻近对象 O(n)
public class CollisionSystem
{
    private UniformGrid&lt;Enemy&gt; _grid;

    private void Update()
    {
        foreach (var enemy in _enemies)
        {
            var nearby = _grid.Query(enemy.Position, enemy.Radius);
            foreach (var other in nearby)
            {
                if (enemy.Id &lt; other.Id)
                {
                    float dist = Vector3.Distance(enemy.Position, other.Position);
                    if (dist &lt; enemy.Radius + other.Radius)
                        ResolveCollision(enemy, other);
                }
            }
        }
        // 1000 个敌人，每个平均只检查 ~10 个邻近对象
        // = ~5000 次距离计算（vs 暴力的 ~500,000 次）
    }
}
