角色职责Unity/C# 对应空间分区接口定义插入、移除、查询的统一契约ISpatialPartition&lt;T&gt;具体分区结构按不同策略组织空间数据UniformGrid、QuadTree、Octree、SpatialHash游戏对象持有位置信息的实体Enemy、Bullet、Item查询结果返回指定范围内的邻近对象List&lt;T&gt;、堆栈分配的缓冲区



                  空间分区与 visitor-pattern-访问者 的关系



空间分区的查询操作本质上是一种”空间选择性访问”——只访问满足空间条件的对象。这与 visitor 的”按类型选择性访问”结构类似。两者都是”过滤+访问”的模式。


游戏开发深度
均匀网格（Uniform Grid）：2D 游戏的最佳选择
最简单高效的空间分区——将空间划分为等大小的格子，每个格子维护一个对象列表：
// 均匀网格实现——2D 游戏的最佳选择
public class UniformGrid&lt;T&gt; where T : class
{
    private readonly List&lt;T&gt;[,] _cells;
    private readonly float _cellSize;
    private readonly int _gridWidth;
    private readonly int _gridHeight;
    private readonly Func&lt;T, Vector2&gt; _getPosition;

    public UniformGrid(float width, float height, float cellSize, Func&lt;T, Vector2&gt; getPosition)
    {
        _cellSize = cellSize;
        _getPosition = getPosition;
        _gridWidth = Mathf.CeilToInt(width / cellSize);
        _gridHeight = Mathf.CeilToInt(height / cellSize);
        _cells = new List&lt;T&gt;[_gridWidth, _gridHeight];

        for (int x = 0; x &lt; _gridWidth; x++)
            for (int y = 0; y &lt; _gridHeight; y++)
                _cells[x, y] = new List&lt;T&gt;();
    }

    public void Insert(T obj)
    {
        var pos = _getPosition(obj);
        var (x, y) = PositionToCell(pos);
        if (InBounds(x, y)) _cells[x, y].Add(obj);
    }

    public void Remove(T obj)
    {
        var pos = _getPosition(obj);
        var (x, y) = PositionToCell(pos);
        if (InBounds(x, y)) _cells[x, y].Remove(obj);
    }

    public void Move(T obj, Vector2 oldPos)
    {
        var (oldX, oldY) = PositionToCell(oldPos);
        var (newX, newY) = PositionToCell(_getPosition(obj));

        if (oldX == newX &amp;&amp; oldY == newY) return;
        if (InBounds(oldX, oldY)) _cells[oldX, oldY].Remove(obj);
        if (InBounds(newX, newY)) _cells[newX, newY].Add(obj);
    }

    public List&lt;T&gt; Query(Vector2 pos, float radius)
    {
        var result = new List&lt;T&gt;();
        int minCellX = Mathf.Max(0, CellCoord(pos.x - radius));
        int maxCellX = Mathf.Min(_gridWidth - 1, CellCoord(pos.x + radius));
        int minCellY = Mathf.Max(0, CellCoord(pos.y - radius));
        int maxCellY = Mathf.Min(_gridHeight - 1, CellCoord(pos.y + radius));

        for (int x = minCellX; x &lt;= maxCellX; x++)
            for (int y = minCellY; y &lt;= maxCellY; y++)
                result.AddRange(_cells[x, y]);

        return result;
    }

    private (int x, int y) PositionToCell(Vector2 pos) =&gt; (CellCoord(pos.x), CellCoord(pos.y));
    private int CellCoord(float worldPos) =&gt; Mathf.FloorToInt(worldPos / _cellSize);
    private bool InBounds(int x, int y) =&gt; x &gt;= 0 &amp;&amp; x &lt; _gridWidth &amp;&amp; y &gt;= 0 &amp;&amp; y &lt; _gridHeight;
}



                  格子大小的选择 



格子大小 ≈ 最大碰撞对象直径。太大：每格对象过多，退化回暴力检测。太小：对象跨多格，重复检查。经验法则：cellSize = 2 * maxObjectRadius。


四叉树（QuadTree）：2D 稀疏分布
递归四分空间，适合 2D 稀疏分布的对象：
// 四叉树实现
public class QuadTree&lt;T&gt; where T : class
{
    private readonly Rect _bounds;
    private readonly int _capacity;
    private readonly List&lt;(T obj, Vector2 pos)&gt; _objects;
    private QuadTree&lt;T&gt;[] _children;
    private bool _divided;

    public QuadTree(Rect bounds, int capacity = 4)
    {
        _bounds = bounds;
        _capacity = capacity;
        _objects = new List&lt;(T, Vector2)&gt;(_capacity);
        _children = new QuadTree&lt;T&gt;[4];
    }

    public bool Insert(T obj, Vector2 pos)
    {
        if (!_bounds.Contains(pos)) return false;

        if (_objects.Count &lt; _capacity &amp;&amp; !_divided)
        {
            _objects.Add((obj, pos));
            return true;
        }

        if (!_divided) Subdivide();

        foreach (var child in _children)
            if (child.Insert(obj, pos)) return true;

        return false;
    }

    private void Subdivide()
    {
        float halfW = _bounds.width / 2f;
        float halfH = _bounds.height / 2f;
        float x = _bounds.xMin;
        float y = _bounds.yMin;

        _children[0] = new QuadTree&lt;T&gt;(new Rect(x, y, halfW, halfH), _capacity);
        _children[1] = new QuadTree&lt;T&gt;(new Rect(x + halfW, y, halfW, halfH), _capacity);
        _children[2] = new QuadTree&lt;T&gt;(new Rect(x, y + halfH, halfW, halfH), _capacity);
        _children[3] = new QuadTree&lt;T&gt;(new Rect(x + halfW, y + halfH, halfW, halfH), _capacity);
        _divided = true;

        foreach (var (obj, pos) in _objects)
            foreach (var child in _children)
                if (child.Insert(obj, pos)) break;
        _objects.Clear();
    }

    public List&lt;T&gt; Query(Rect range)
    {
        var result = new List&lt;T&gt;();
        if (!_bounds.Overlaps(range)) return result;

        foreach (var (obj, pos) in _objects)
            if (range.Contains(pos)) result.Add(obj);

        if (_divided)
            foreach (var child in _children)
                result.AddRange(child.Query(range));

        return result;
    }
}
八叉树（Octree）：3D 空间
八叉树是四叉树的三维扩展，每个节点分裂为 8 个子节点：
// 八叉树：3D 空间分区
public class Octree&lt;T&gt; where T : class
{
    private readonly Bounds _bounds;
    private readonly int _capacity;
    private readonly List&lt;(T obj, Vector3 pos)&gt; _objects;
    private Octree&lt;T&gt;[] _children;
    private bool _divided;

    public Octree(Bounds bounds, int capacity = 8)
    {
        _bounds = bounds;
        _capacity = capacity;
        _objects = new List&lt;(T, Vector3)&gt;(capacity);
        _children = new Octree&lt;T&gt;[8];
    }

    public bool Insert(T obj, Vector3 pos)
    {
        if (!_bounds.Contains(pos)) return false;

        if (_objects.Count &lt; _capacity &amp;&amp; !_divided)
        {
            _objects.Add((obj, pos));
            return true;
        }

        if (!_divided) Subdivide();

        foreach (var child in _children)
            if (child.Insert(obj, pos)) return true;

        return false;
    }

    private void Subdivide()
    {
        var size = _bounds.size / 2f;
        var center = _bounds.center;

        for (int i = 0; i &lt; 8; i++)
        {
            float x = center.x + (i &amp; 1) * size.x - size.x / 2f;
            float y = center.y + ((i &gt;&gt; 1) &amp; 1) * size.y - size.y / 2f;
            float z = center.z + ((i &gt;&gt; 2) &amp; 1) * size.z - size.z / 2f;
            _children[i] = new Octree&lt;T&gt;(new Bounds(new Vector3(x, y, z), size), _capacity);
        }

        _divided = true;
        foreach (var (obj, pos) in _objects)
            foreach (var child in _children)
                if (child.Insert(obj, pos)) break;
        _objects.Clear();
    }

    public List&lt;T&gt; Query(Bounds range)
    {
        var result = new List&lt;T&gt;();
        if (!_bounds.Intersects(range)) return result;

        foreach (var (obj, pos) in _objects)
            if (range.Contains(pos)) result.Add(obj);

        if (_divided)
            foreach (var child in _children)
                result.AddRange(child.Query(range));

        return result;
    }
}
空间哈希（Spatial Hash）：动态场景的最佳性价比
用哈希函数将连续坐标映射到离散桶，动态场景中性能极佳：
// 空间哈希实现——动态场景的最佳性价比
public class SpatialHash&lt;T&gt; where T : class
{
    private readonly Dictionary&lt;int, List&lt;T&gt;&gt; _buckets = new();
    private readonly float _cellSize;
    private readonly Func&lt;T, Vector3&gt; _getPosition;

    public SpatialHash(float cellSize, Func&lt;T, Vector3&gt; getPosition)
    {
        _cellSize = cellSize;
        _getPosition = getPosition;
    }

    public void Insert(T obj)
    {
        int hash = HashPosition(_getPosition(obj));
        if (!_buckets.TryGetValue(hash, out var bucket))
        {
            bucket = new List&lt;T&gt;();
            _buckets[hash] = bucket;
        }
        bucket.Add(obj);
    }

    public void Remove(T obj)
    {
        int hash = HashPosition(_getPosition(obj));
        if (_buckets.TryGetValue(hash, out var bucket))
        {
            bucket.Remove(obj);
            if (bucket.Count == 0) _buckets.Remove(hash);
        }
    }

    public List&lt;T&gt; Query(Vector3 pos, float radius)
    {
        var result = new List&lt;T&gt;();
        float r = radius + _cellSize;

        int minCellX = CellCoord(pos.x - r);
        int maxCellX = CellCoord(pos.x + r);
        int minCellZ = CellCoord(pos.z - r);
        int maxCellZ = CellCoord(pos.z + r);

        for (int x = minCellX; x &lt;= maxCellX; x++)
        {
            for (int z = minCellZ; z &lt;= maxCellZ; z++)
            {
                int hash = HashCell(x, 0, z);
                if (_buckets.TryGetValue(hash, out var bucket))
                {
                    foreach (var obj in bucket)
                    {
                        if (Vector3.Distance(pos, _getPosition(obj)) &lt;= radius)
                            result.Add(obj);
                    }
                }
            }
        }
        return result;
    }

    public void Clear() =&gt; _buckets.Clear();

    private int HashPosition(Vector3 pos) =&gt;
        HashCell(CellCoord(pos.x), CellCoord(pos.y), CellCoord(pos.z));

    private int HashCell(int x, int y, int z)
    {
        unchecked { return x * 73856093 ^ y * 19349663 ^ z * 83492791; }
    }

    private int CellCoord(float worldPos) =&gt; Mathf.FloorToInt(worldPos / _cellSize);
}



                  空间哈希 vs 均匀网格 



空间哈希 = 按需分配的网格。只在有对象的位置创建桶，内存随对象数量缩放。均匀网格 = 预分配全部格子，内存随地图大小缩放。对象少、地图大 → 空间哈希更省内存。对象多且分布均匀 → 均匀网格更快（无哈希计算开销）。


