                  Unity 的静态碰撞体优化 



含 static 标记的 Collider 会被放入静态 AABB 树，不需要每帧重建。动态 Collider 使用增量更新的动态树。确保标记真正不动的物体为 static 可显著减少 Broadphase 开销。


DOTS 中的空间查询
DOTS/ECS 中的空间查询通过 NativeMultiHashMap 或 Unity Physics 完成——参见 dots-ecs-数据导向：
// DOTS 空间查询：用 NativeMultiHashMap 实现均匀网格
[BurstCompile]
public struct GridQueryJob : IJobParallelFor
{
    [ReadOnly] public NativeArray&lt;Position&gt; Positions;
    [ReadOnly] public NativeMultiHashMap&lt;int, int&gt; Grid;
    public float CellSize;
    public float QueryRadius;

    public void Execute(int index)
    {
        var pos = Positions[index].Value;
        int minCellX = (int)math.floor((pos.x - QueryRadius) / CellSize);
        int maxCellX = (int)math.floor((pos.x + QueryRadius) / CellSize);

        for (int cx = minCellX; cx &lt;= maxCellX; cx++)
        {
            int hash = cx * 73856093;
            if (Grid.TryGetFirstValue(hash, out int entityIdx, out var it))
            {
                do
                {
                    float dist = math.distance(pos, Positions[entityIdx].Value);
                    if (dist &lt;= QueryRadius) { /* 碰撞处理 */ }
                } while (Grid.TryGetNextValue(out entityIdx, ref it));
            }
        }
    }
}
完整的均匀网格碰撞检测 C# 实现
// 生产级均匀网格碰撞系统
public class GridCollisionSystem : MonoBehaviour
{
    [SerializeField] private float _cellSize = 2f;
    [SerializeField] private float _worldSize = 100f;

    private Dictionary&lt;(int, int), List&lt;CollisionEntity&gt;&gt; _grid = new();
    private List&lt;CollisionEntity&gt; _entities = new();

    public struct CollisionEntity
    {
        public int Id;
        public Vector2 Position;
        public float Radius;
    }

    public void Register(CollisionEntity entity)
    {
        _entities.Add(entity);
        AddToGrid(entity);
    }

    public void UpdateEntity(int id, Vector2 newPos)
    {
        int idx = _entities.FindIndex(e =&gt; e.Id == id);
        if (idx &lt; 0) return;

        var oldEntity = _entities[idx];
        var (oldCX, oldCY) = WorldToCell(oldEntity.Position);
        var (newCX, newCY) = WorldToCell(newPos);

        if (oldCX != newCX || oldCY != newCY)
        {
            RemoveFromGrid(oldEntity);
            var newEntity = oldEntity;
            newEntity.Position = newPos;
            _entities[idx] = newEntity;
            AddToGrid(newEntity);
        }
        else
        {
            var newEntity = oldEntity;
            newEntity.Position = newPos;
            _entities[idx] = newEntity;
        }
    }

    public List&lt;(int, int)&gt; DetectCollisions()
    {
        var pairs = new List&lt;(int, int)&gt;();
        var checkedPairs = new HashSet&lt;(int, int)&gt;();

        foreach (var entity in _entities)
        {
            var (cx, cy) = WorldToCell(entity.Position);
            int searchRadius = Mathf.CeilToInt(entity.Radius / _cellSize) + 1;

            for (int dx = -searchRadius; dx &lt;= searchRadius; dx++)
            {
                for (int dy = -searchRadius; dy &lt;= searchRadius; dy++)
                {
                    var key = (cx + dx, cy + dy);
                    if (!_grid.TryGetValue(key, out var cellEntities)) continue;

                    foreach (var other in cellEntities)
                    {
                        if (entity.Id &gt;= other.Id) continue;
                        var pairKey = (entity.Id, other.Id);
                        if (checkedPairs.Contains(pairKey)) continue;
                        checkedPairs.Add(pairKey);

                        float dist = Vector2.Distance(entity.Position, other.Position);
                        if (dist &lt; entity.Radius + other.Radius)
                            pairs.Add(pairKey);
                    }
                }
            }
        }

        return pairs;
    }

    private void AddToGrid(CollisionEntity entity)
    {
        var key = WorldToCell(entity.Position);
        if (!_grid.ContainsKey(key)) _grid[key] = new List&lt;CollisionEntity&gt;();
        _grid[key].Add(entity);
    }

    private void RemoveFromGrid(CollisionEntity entity)
    {
        var key = WorldToCell(entity.Position);
        if (_grid.TryGetValue(key, out var cell)) cell.Remove(entity);
    }

    private (int, int) WorldToCell(Vector2 pos) =&gt;
        (Mathf.FloorToInt(pos.x / _cellSize), Mathf.FloorToInt(pos.y / _cellSize));
}
