基本实现
public interface ICharacterState
{
    void Enter();
    void Update();
    void Exit();
}

public class IdleState : ICharacterState
{
    private readonly Character _ctx;
    public IdleState(Character ctx) =&gt; _ctx = ctx;

    public void Enter() =&gt; Debug.Log(&quot;进入待机&quot;);
    public void Update()
    {
        if (Input.GetKeyDown(KeyCode.W))
            _ctx.TransitionTo(new RunState(_ctx));
    }
    public void Exit() =&gt; Debug.Log(&quot;退出待机&quot;);
}

public class RunState : ICharacterState
{
    private readonly Character _ctx;
    public RunState(Character ctx) =&gt; _ctx = ctx;

    public void Enter() =&gt; Debug.Log(&quot;进入奔跑&quot;);
    public void Update()
    {
        if (!Input.GetKey(KeyCode.W))
            _ctx.TransitionTo(new IdleState(_ctx));
    }
    public void Exit() =&gt; Debug.Log(&quot;退出奔跑&quot;);
}

public class Character : MonoBehaviour
{
    private ICharacterState _state;

    private void Start() =&gt; TransitionTo(new IdleState(this));

    public void TransitionTo(ICharacterState state)
    {
        _state?.Exit();
        _state = state;
        _state.Enter();
    }

    private void Update() =&gt; _state.Update();
}
入口行为与出口行为（GPP 关键洞察）



                  Enter()/Exit() 是状态模式的核心价值 



GPP 指出：没有入口/出口行为的状态模式只是策略模式的别名。Enter() 让状态自己管理”进入时做什么”（播放动画、启用碰撞体），Exit() 让状态管理”离开时做什么”（停止粒子、清除计时器）。这比依赖前一个状态来清理更安全——前一个状态不知道下一个状态是什么。


// 没有 Enter/Exit：转换时手动清理，容易遗漏
public void TransitionTo(PlayerState newState)
{
    // 必须知道当前状态的所有清理逻辑
    if (State == PlayerState.Run) StopRunningSound();
    if (State == PlayerState.Jump) ResetGravity();
    State = newState;
    // 必须知道新状态的所有初始化逻辑
    if (State == PlayerState.Idle) PlayIdleAnimation();
}

// 有 Enter/Exit：每个状态自己管自己
public void TransitionTo(ICharacterState state)
{
    _state?.Exit();   // 当前状态自己清理
    _state = state;
    _state.Enter();   // 新状态自己初始化
}
静态状态 vs 实例化状态



                  无数据的状态用享元，有数据的状态用实例 



GPP 区分两种风格：静态状态（所有字段在编译期确定，可共享单一实例，是 flyweight-pattern-享元 的应用）和实例化状态（状态持有运行时数据如计时器、计数器，每次转换需 new）。


// 静态状态：无数据，共享实例，零 GC
public class IdleState : ICharacterState
{
    public static readonly IdleState Instance = new();
    private IdleState() { }
    public void Enter() =&gt; Debug.Log(&quot;进入待机&quot;);
    public void Update() { /* ... */ }
    public void Exit() =&gt; Debug.Log(&quot;退出待机&quot;);
}

// 使用：_ctx.TransitionTo(IdleState.Instance); // 无分配

// 实例化状态：有数据，每次 new
public class AttackState : ICharacterState
{
    private readonly Character _ctx;
    private float _attackTimer;  // 运行时数据
    public AttackState(Character ctx) =&gt; _ctx = ctx;
    public void Enter() =&gt; _attackTimer = 0.5f;
    public void Update() { _attackTimer -= Time.deltaTime; /* ... */ }
    public void Exit() { }
}



                  选择原则 



状态只有行为无数据 → 静态实例。状态需要计时器/计数器等运行时数据 → 实例化。频繁转换的状态（如 AI 每帧切换）可考虑对象池复用实例化状态，避免 GC。


游戏开发深度
状态模式的完整演进路径
GPP 描述了一条从简单到复杂的渐进路径，每一步解决前一步的痛点：
graph LR
    A[&quot;枚举+switch&lt;br&gt;最简单但不可扩展&quot;] --&gt; B[&quot;状态模式&lt;br&gt;封装行为和转换&quot;]
    B --&gt; C[&quot;并发状态机&lt;br&gt;避免笛卡尔积&quot;]
    C --&gt; D[&quot;层次状态机&lt;br&gt;子状态继承转换&quot;]
    D --&gt; E[&quot;下推自动机&lt;br&gt;状态栈支持回退&quot;]




































阶段解决的问题Unity 典型场景枚举 + switch3 个以内的状态简单开关（开/关/过渡）状态模式状态多、转换逻辑复杂角色动作、AI 行为并发状态机状态组合爆炸角色动作 + 装备系统独立运行层次状态机共享转换逻辑”地面”状态统一处理跳跃，子状态站立/行走/奔跑继承下推自动机需要回退到前一个状态射击后回到之前状态、菜单层级
并发状态机：避免笛卡尔积爆炸
一个角色有”动作”（站立/跑/跳）和”装备”（空手/持枪/持剑），如果合并成一个 FSM，状态数 = 3 x 3 = 9。再加一个”生命状态”（存活/濒死/死亡），就是 27 个状态。并发状态机用多个独立 FSM 避免这个问题：
public class Character : MonoBehaviour
{
    private readonly MovementFSM _movement = new();  // 站立/跑/跳
    private readonly EquipmentFSM _equipment = new(); // 空手/持枪/持剑

    private void Update()
    {
        _movement.Update();
        _equipment.Update();
    }
}



                  并发状态机之间的交互 



两个 FSM 独立运行时，如果需要跨 FSM 通信（如”持枪时不能跳跃”），需要额外的协调机制。不要在状态内部直接访问另一个 FSM——用观察者或消息通知。参见 observer-pattern-观察者。


层次状态机（HFSM）
子状态继承父状态的转换，避免在每个子状态重复相同逻辑：
// 层次结构：Grounded 是父状态，Standing/Running 是子状态
//         Grounded
//        /        \
//   Standing    Running
//
// Grounded 统一处理：按 Jump -&gt; JumpState，按 Crouch -&gt; CrouchState
// Standing 专有：按 W -&gt; Running
// Running 专有：松开 W -&gt; Standing

public abstract class GroundedState : ICharacterState
{
    protected readonly Character Ctx;
    protected GroundedState(Character ctx) =&gt; Ctx = ctx;

    public virtual void Enter() { }
    public virtual void Exit() { }

    // 父状态的转换：所有地面状态共享
    public virtual ICharacterState CheckGlobalTransitions()
    {
        if (Input.GetKeyDown(KeyCode.Space))
            return new JumpState(Ctx);
        if (Input.GetKeyDown(KeyCode.C))
            return new CrouchState(Ctx);
        return null; // 无全局转换
    }

    public abstract void Update();
}

public class StandingState : GroundedState
{
    public StandingState(Character ctx) : base(ctx) { }

    public override void Update()
    {
        var globalNext = CheckGlobalTransitions();
        if (globalNext != null) { Ctx.TransitionTo(globalNext); return; }

        if (Input.GetKey(KeyCode.W))
            Ctx.TransitionTo(new RunningState(Ctx));
    }
}



                  HFSM 实现 



Unity 社区常用 HFSM 库：Stateless（.NET 标准，支持 DOT 图导出）、Sirenix Odin State Machine（Inspector 可视化）。简单项目手写 HFSM 即可，复杂 AI 考虑行为树。


下推自动机：状态栈
支持”回到上一个状态”——把状态压栈，完成后弹出：
public class Character : MonoBehaviour
{
    private readonly Stack&lt;ICharacterState&gt; _stateStack = new();
    private ICharacterState _current;

    public void PushState(ICharacterState state)
    {
        _stateStack.Push(_current);
        _current?.Exit();
        _current = state;
        _current.Enter();
    }

    public void PopState()
    {
        _current?.Exit();
        _current = _stateStack.Count &gt; 0 ? _stateStack.Pop() : new IdleState(this);
        _current.Enter();
    }

    // 示例：射击后回到之前状态
    // PushState(new ShootState(this));  -&gt; 射击
    // ShootState 结束时 -&gt; PopState(); -&gt; 回到之前状态
}



                  状态栈过深 



如果栈深度不受控（如下推自动机循环压栈），内存会持续增长。加深度上限或改用显式目标状态。


状态模式与 MonoBehaviour 生命周期





























生命周期状态模式关注点Awake初始化 Context，设置初始状态OnEnable如果状态需要响应全局事件，在此订阅Update调用 _state.Update()OnDisable状态可能需要暂停（不转换，但停止 Update）OnDestroy清理状态持有的资源
参见 monobehaviour-lifecycle-生命周期。



                  MonoBehaviour 状态的序列化陷阱 



ICharacterState 是接口引用，Unity 无法序列化。游戏存档/加载时需要把当前状态映射为可序列化的标识（枚举或字符串），重建状态对象：


// 存档：状态 -&gt; 字符串
public string SaveState() =&gt; _state.GetType().Name;

// 读档：字符串 -&gt; 状态
public void LoadState(string stateName)
{
    _state = stateName switch
    {
        nameof(IdleState) =&gt; new IdleState(this),
        nameof(RunState) =&gt; new RunState(this),
        _ =&gt; new IdleState(this)
    };
}
Job System 中的状态管理
job-system-作业系统 要求数据是 blittable 类型，状态模式中的 ICharacterState 接口引用无法在 Job 中使用。方案：
// Burst 兼容：用枚举 + NativeArray 存状态数据
public enum AIState : byte { Patrol, Chase, Attack, Flee }

public struct AIData
{
    public AIState State;
    public float StateTimer;
    public float3 TargetPosition;
}

// 在 Job 中直接读写 NativeArray&lt;AIData&gt;
[BurstCompile]
public struct AIUpdateJob : IJobParallelFor
{
    public NativeArray&lt;AIData&gt; Data;
    public void Execute(int index)
    {
        var d = Data[index];
        d.StateTimer -= 0.016f;
        // 状态转换用 switch（在 Burst 中这是最高效的）
        switch (d.State)
        {
            case AIState.Patrol:
                if (CanSeePlayer(d)) d.State = AIState.Chase;
                break;
            // ...
        }
        Data[index] = d;
    }
}



                  Burst 中 switch 优于状态模式 



Burst 编译器对 switch 有专门的优化（跳转表），而接口虚调用在 Burst 中不被支持。在 Job System 热路径中，枚举 + switch 比状态模式更快。状态模式适合主线程复杂逻辑，Burst 路径用数据驱动。参见 job-system-作业系统 和 burst-compiler-Burst编译。


变体与演进
转换表（Transition Table）
将转换逻辑从状态类中抽出，集中管理：
// 转换表：状态 + 触发 -&gt; 目标状态
public class StateMachine
{
    private readonly Dictionary&lt;(Type, string), Func&lt;ICharacterState&gt;&gt; _transitions = new();
    private ICharacterState _current;

    public void AddTransition&lt;TFrom&gt;(string trigger, Func&lt;ICharacterState&gt; toFactory)
        =&gt; _transitions[(typeof(TFrom), trigger)] = toFactory;

    public void FireTrigger(string trigger)
    {
        if (_transitions.TryGetValue((_current.GetType(), trigger), out var factory))
            TransitionTo(factory());
    }
}

// 注册
sm.AddTransition&lt;IdleState&gt;(&quot;W_Pressed&quot;, () =&gt; new RunState(ctx));
sm.AddTransition&lt;RunState&gt;(&quot;W_Released&quot;, () =&gt; new IdleState(ctx));



                  转换表 vs 状态内部转换 



转换表集中了”哪些转换合法”，方便审查和可视化，但每次加状态要改表。状态内部转换分散但自包含。GPP 建议：状态少用内部转换，状态多用转换表。


字符串键转换表 FSM（实用示例）
跑酷游戏角色有 3 种状态（跑动、一段跳、二段跳），用字符串常量标识状态和事件，转换表注册合法转换和回调：
// 状态与事件常量
public class PlayerState
{
    public const string Run = &quot;Run&quot;;
    public const string Jump = &quot;Jump&quot;;
    public const string DoubleJump = &quot;DoubleJump&quot;;
}

public class PlayerEvent
{
    public const string EVENT_JUMP = &quot;EVENT_JUMP&quot;;
    public const string EVENT_RUN = &quot;EVENT_RUN&quot;;
}

// 使用 FSM 注册状态和转换
private void Start()
{
    _fsm.AddState(PlayerState.Run);
    _fsm.AddState(PlayerState.Jump);
    _fsm.AddState(PlayerState.DoubleJump);

    // 事件 + 源状态 + 目标状态 + 转换回调
    _fsm.AddTranslateState(PlayerEvent.EVENT_JUMP, PlayerState.Run, PlayerState.Jump, _ =&gt; Jump());
    _fsm.AddTranslateState(PlayerEvent.EVENT_JUMP, PlayerState.Jump, PlayerState.DoubleJump, _ =&gt; DoubleJump());
    _fsm.AddTranslateState(PlayerEvent.EVENT_RUN, PlayerState.Jump, PlayerState.Run, _ =&gt; Run());
    _fsm.AddTranslateState(PlayerEvent.EVENT_RUN, PlayerState.DoubleJump, PlayerState.Run, _ =&gt; Run());

    _fsm.StartState(PlayerState.Jump);
}



                  字符串键 FSM 的权衡 



字符串键缺少编译期检查（拼错只在运行时暴露），但对快速原型和小型项目足够用。生产代码建议用枚举或泛型 FSM 库（如 Stateless）替代字符串键，获得编译期安全和重构支持。


状态模式 → 行为树 → 规划系统
graph LR
    A[&quot;状态模式/FSM&lt;br&gt;确定性的状态转换&quot;] --&gt; B[&quot;行为树&lt;br&gt;条件驱动的决策树&quot;]
    B --&gt; C[&quot;GOAP/规划系统&lt;br&gt;目标驱动的自动规划&quot;]




                  状态模式不是图灵完全的 



GPP 明确指出：FSM/状态模式只能表达有限个状态和预定义转换。复杂 AI 需要行为树（条件驱动的树结构决策）或 GOAP（目标驱动的自动规划，搜索从当前状态到目标状态的行动序列）。状态模式是 AI 的起点，不是终点。


反模式



                  状态转换散落在各状态类中 



每个状态类决定自己转到哪个状态，转换逻辑分散。如果状态 A 不知道状态 B 的存在（解耦），却要转到 B，耦合就通过状态类本身泄露了。可用转换表（Transition Table）集中管理转换规则。





                  在 Enter/Exit 中执行耗时操作 



Enter() 和 Exit() 是同步调用。在其中加载资源、等待异步操作会阻塞状态转换。耗时初始化应拆为”进入中”过渡状态，完成后才正式进入。





                  状态类持有 MonoBehaviour 引用并直接操作 



状态类如果直接调用 GetComponent&lt;&gt;() 或访问大量 MonoBehaviour 字段，会变成”披着状态模式外衣的 god class”。状态类应通过 Context 接口访问数据，保持职责单一。





                  忽略 Unity 的帧率波动 



状态的 Update() 依赖 Time.deltaTime，但某些帧 deltaTime 可能异常大（如加载卡顿、切后台回来）。状态计时器应加 Mathf.Min(deltaTime, maxDelta) 上限保护。





                  把所有逻辑塞进一个状态 



如果某个状态的 Update() 超过 100 行，通常意味着这个状态应该拆分为子状态或并发状态机。参见”层次状态机”章节。


权衡与选择

用状态模式：状态少（3-8个）、转换逻辑简单时
用 FSM 库：状态多、转换复杂、需要可视化编辑时（如 Stateless、Sirenix Odin State Machine）
用策略：行为可替换但由客户端选择时（状态是自动切换，策略是外部选择——结构相似，意图不同）
用行为树：AI 决策需要条件组合、优先级、并行执行时
用 GOAP：AI 需要动态规划行动序列时

参见 strategy-pattern-策略 了解策略与状态的意图差异。
