patterns-设计模式/strategy-pattern-策略.content:
策略（Strategy）
核心思想
定义一系列算法，将每种算法封装为独立类，使它们可以互相替换。让算法的变化独立于使用它的客户端。
问题动机
不用策略模式会怎样？

客户端内嵌大量 if-else / switch，每新增一种算法就要改客户端，违反开闭原则
算法逻辑与业务逻辑耦合，无法独立测试、无法复用
运行时无法切换算法——想换一种寻路？只能改代码重编

策略模式的核心价值：把”用什么算法”的决策从”算法怎么执行”中剥离出来。
结构图
classDiagram
    class Context {
        -IStrategy strategy
        +SetStrategy(IStrategy)
        +Execute()
    }
    class IStrategy {
        &lt;&lt;interface&gt;&gt;
        +Algorithm()
    }
    class ConcreteStrategyA {
        +Algorithm()
    }
    class ConcreteStrategyB {
        +Algorithm()
    }

    Context --&gt; IStrategy : uses
    IStrategy &lt;|.. ConcreteStrategyA
    IStrategy &lt;|.. ConcreteStrategyB

参与者说明：





















角色职责Context（上下文）持有策略引用，将算法委托给策略对象；不关心具体算法细节IStrategy（策略接口）声明算法的公共接口，Context 通过它调用具体策略ConcreteStrategy（具体策略）实现算法的具体变体，每个变体一个类
工作原理
public interface IDamageStrategy
{
    int Calculate(int baseDamage, Character target);
}

public class NormalDamage : IDamageStrategy
{
    public int Calculate(int baseDamage, Character target) =&gt; baseDamage;
}

public class CriticalDamage : IDamageStrategy
{
    public int Calculate(int baseDamage, Character target) =&gt; baseDamage * 2;
}

public class ElementalDamage : IDamageStrategy
{
    private readonly string _element;
    public ElementalDamage(string element) =&gt; _element = element;

    public int Calculate(int baseDamage, Character target)
    {
        var multiplier = target.IsWeakTo(_element) ? 1.5f : 1f;
        return Mathf.RoundToInt(baseDamage * multiplier);
    }
}

// 上下文：使用策略的角色
public class Weapon
{
    public IDamageStrategy DamageStrategy { get; set; }

    public int Attack(int baseDamage, Character target) =&gt;
        DamageStrategy.Calculate(baseDamage, target);
}
游戏开发深度
AI 行为策略：ScriptableObject 配置 + 策略工厂
AI 行为是策略模式最经典的游戏场景。用 ScriptableObject 做策略配置，可在 Inspector 中热调，无需改代码。
public abstract class AiBehaviorStrategy : ScriptableObject
{
    public abstract IEnumerator Execute(AiController agent);
}

[CreateAssetMenu(menuName = &quot;AI/Aggressive Strategy&quot;)]
public class AggressiveStrategy : AiBehaviorStrategy
{
    public float chaseRange = 10f;
    public float attackRange = 2f;

    public override IEnumerator Execute(AiController agent)
    {
        var target = agent.FindNearestEnemy(chaseRange);
        if (target == null) yield break;

        yield return agent.MoveToward(target.position);
        if (Vector3.Distance(agent.transform.position, target.position) &lt;= attackRange)
            yield return agent.Attack();
    }
}

// 策略工厂：根据配置创建策略实例
public static class AiStrategyFactory
{
    public static AiBehaviorStrategy Create(AiProfile profile)
    {
        // 从 Addressables 或 Resources 加载对应的 ScriptableObject
        return profile.strategyAsset;
    }
}



                  ScriptableObject 策略实例是无状态的天然享元 



AiBehaviorStrategy 的字段是配置数据（chaseRange 等），不持有运行时状态。多个 agent 可共享同一个 SO 实例——这正是 flyweight-pattern-享元 的应用。运行时状态放在 AiController 上，策略只读配置 + 操作 agent。


伤害计算管线：策略的递归组合
实际项目的伤害计算不是单一策略，而是”基础伤害 → 暴击 → 元素 → 穿透”的管线组合。用装饰器风格的策略链实现：
// 策略管道：每个策略包装下一个策略
public class DamagePipeline
{
    private readonly List&lt;IDamageModifier&gt; _modifiers = new();

    public DamagePipeline Add(IDamageModifier modifier)
    {
        _modifiers.Add(modifier);
        return this;
    }

    public int Calculate(int baseDamage, Character attacker, Character defender)
    {
        var ctx = new DamageContext(baseDamage, attacker, defender);
        foreach (var mod in _modifiers)
            mod.Apply(ctx);
        return ctx.FinalDamage;
    }
}

public class DamageContext
{
    public int BaseDamage;
    public int FinalDamage;
    public Character Attacker;
    public Character Defender;
    public bool IsCritical;

    public DamageContext(int baseDamage, Character attacker, Character defender)
    {
        BaseDamage = baseDamage;
        FinalDamage = baseDamage;
        Attacker = attacker;
        Defender = defender;
    }
}

public interface IDamageModifier
{
    void Apply(DamageContext ctx);
}

// 暴击策略
public class CriticalModifier : IDamageModifier
{
    private readonly float _critMultiplier;
    private readonly float _critChance;

    public CriticalModifier(float critChance = 0.2f, float critMultiplier = 2f)
    {
        _critChance = critChance;
        _critMultiplier = critMultiplier;
    }

    public void Apply(DamageContext ctx)
    {
        if (Random.value &lt; _critChance)
        {
            ctx.IsCritical = true;
            ctx.FinalDamage = Mathf.RoundToInt(ctx.FinalDamage * _critMultiplier);
        }
    }
}

// 元素策略
public class ElementalModifier : IDamageModifier
{
    private readonly Element _element;
    public ElementalModifier(Element element) =&gt; _element = element;

    public void Apply(DamageContext ctx)
    {
        if (ctx.Defender.IsWeakTo(_element))
            ctx.FinalDamage = Mathf.RoundToInt(ctx.FinalDamage * 1.5f);
    }
}



                  这是策略 + 责任链的混合形态 



管线中每个 modifier 是独立的策略，但它们的组合方式是责任链。相比 GoF 原始策略，管线模式更灵活——可以动态增删 modifier，且每个 modifier 只关心自己的逻辑。


寻路策略切换：A* / Dijkstra / NavMesh 运行时切换
不同场景需要不同寻路算法：室内用 A* grid，室外用 NavMesh，全图搜索用 Dijkstra。
public interface IPathfindingStrategy
{
    List&lt;Vector3&gt; FindPath(Vector3 from, Vector3 to);
}

public class AStarGridStrategy : IPathfindingStrategy
{
    private readonly Grid _grid;
    public AStarGridStrategy(Grid grid) =&gt; _grid = grid;

    public List&lt;Vector3&gt; FindPath(Vector3 from, Vector3 to)
        =&gt; AStarPathfinder.Find(_grid, from, to);
}

public class NavMeshStrategy : IPathfindingStrategy
{
    public List&lt;Vector3&gt; FindPath(Vector3 from, Vector3 to)
    {
        var path = new NavMeshPath();
        NavMesh.CalculatePath(from, to, NavMesh.AllAreas, path);
        return path.corners.ToList();
    }
}

// 上下文：根据场景自动切换
public class PathfindingController : MonoBehaviour
{
    private IPathfindingStrategy _strategy;

    private void OnEnable()
    {
        // 室内场景用 Grid，室外用 NavMesh
        _strategy = SceneManager.GetActiveScene().name.Contains(&quot;Indoor&quot;)
            ? new AStarGridStrategy(GetComponent&lt;Grid&gt;())
            : new NavMeshStrategy();
    }

    public List&lt;Vector3&gt; GetPath(Vector3 target)
        =&gt; _strategy.FindPath(transform.position, target);
}
输入系统 + 策略选择
Unity 新输入系统天然适配策略：输入事件触发策略选择，策略执行具体行为。
// 策略选择器：根据输入映射到策略
public class CombatStrategySelector : MonoBehaviour
{
    [SerializeField] private PlayerInput _playerInput;

    private Dictionary&lt;string, ICombatStrategy&gt; _strategies;
    private ICombatStrategy _current;

    private void Awake()
    {
        _strategies = new Dictionary&lt;string, ICombatStrategy&gt;
        {
            [&quot;Melee&quot;] = new MeleeStrategy(),
            [&quot;Ranged&quot;] = new RangedStrategy(),
            [&quot;Magic&quot;] = new MagicStrategy()
        };
        _current = _strategies[&quot;Melee&quot;];

        _playerInput.actions[&quot;SwitchWeapon&quot;].performed += OnSwitchWeapon;
    }

    private void OnSwitchWeapon(InputAction.CallbackContext ctx)
    {
        var weaponType = ctx.control.name; // &quot;1&quot; → Melee, &quot;2&quot; → Ranged…
        if (_strategies.TryGetValue(weaponType, out var strategy))
            _current = strategy;
    }

    public void Attack() =&gt; _current.Execute(this);
}
C# 轻量策略：delegate / Func&lt;T&gt;
不是所有策略都需要独立类。C# 的 delegate 和 Func&lt;T&gt; 是零样板的策略替换：
// 用 Func 替代策略接口——适合策略逻辑简单、无状态的场景
public class WeaponLite
{
    public Func&lt;int, Character, int&gt; DamageCalc { get; set; } = (dmg, _) =&gt; dmg;

    public void SetCritical(float chance, float multiplier)
    {
        DamageCalc = (baseDmg, target) =&gt;
            Random.value &lt; chance
                ? Mathf.RoundToInt(baseDmg * multiplier)
                : baseDmg;
    }
}

// 用 delegate 定义策略签名
public delegate int DamageCalcDelegate(int baseDamage, Character target);



                  Func/delegate 的局限 




无法持有配置状态（除非用闭包捕获，但闭包会分配堆内存）
无法序列化到 Inspector
无法用 ScriptableObject 配置
策略逻辑简单且不需要配置时用 Func；需要配置、序列化、共享时用接口 + 类。



策略 + 对象池：避免 GC
策略对象频繁创建会触发 GC。两种规避方式：
// 1. 无状态策略：共享单例，零分配
public static class SharedStrategies
{
    public static readonly IDamageStrategy Normal = new NormalDamage();
    public static readonly IDamageStrategy Critical = new CriticalDamage();
}

// 2. 有状态策略：对象池复用
public class DamageStrategyPool
{
    private readonly Dictionary&lt;Type, Queue&lt;IDamageStrategy&gt;&gt; _pools = new();

    public T Rent&lt;T&gt;() where T : IDamageStrategy, new()
    {
        var type = typeof(T);
        if (_pools.TryGetValue(type, out var queue) &amp;&amp; queue.Count &gt; 0)
            return (T)queue.Dequeue();
        return new T();
    }

    public void Return&lt;T&gt;(T strategy) where T : IDamageStrategy
    {
        var type = typeof(T);
        if (!_pools.ContainsKey(type))
            _pools[type] = new Queue&lt;IDamageStrategy&gt;();
        _pools[type].Enqueue(strategy);
    }
}



                  无状态策略是 flyweight-pattern-享元 的天然应用



策略对象如果只依赖输入参数（不持有字段），就是天然享元——全局共享一个实例即可。只有策略需要配置数据时才考虑池化或 ScriptableObject。


变体与演进








































变体说明适用场景策略管道多个策略按顺序组合（见伤害管线）需要多个策略叠加效果策略表用 Dictionary&lt;Key, IStrategy&gt; 注册策略，按 key 查找策略种类多，需按 ID/名称查找策略 + 工厂用 abstract-factory-抽象工厂 或 factory-method-工厂方法 创建策略对象策略创建逻辑复杂策略 + 享元无状态策略全局共享策略无配置，避免重复分配函数式策略Func&lt;T&gt; / delegate 替代接口逻辑简单、无需序列化策略 + 状态状态模式管理”当前处于什么状态”，策略模式管理”该状态下怎么执行”AI 行为：状态机选策略，策略执行行为
反模式



                  策略泄漏：Context 对策略的内部产生依赖 



如果 Context 代码中出现 if (strategy is CriticalDamage) 这样的类型检查，说明 Context 已经知道策略的内部细节，策略的封装被打破。正确做法是在接口上提供必要的方法（如 IsCritical()），让 Context 通过接口查询。





                  策略爆炸：为微小差异创建大量策略类 



比如为每种暴击倍率（1.5x、2x、2.5x…）各建一个类。应改用参数化策略：一个 CriticalDamageStrategy 类 + critMultiplier 字段，用 ScriptableObject 配置不同倍率实例。





                  策略与状态混淆 



state-pattern-状态 是”内部状态变了，行为自动变”；策略是”外部选择一种算法”。如果你发现策略切换逻辑写在了 Context 内部且按固定规则切换，那可能是在用策略模拟状态——应该改用状态模式。


实践示例

AI 行为策略：Aggressive/Defensive/Patrol，用 ScriptableObject 配置
伤害计算管线：Normal/Critical/Elemental/TrueDamage 递归组合
寻路算法：A*/Dijkstra/NavMesh 运行时切换
武器系统：近战/远程/魔法各有不同行为
排序策略：不同场景用不同排序规则
输入映射：新输入系统的事件 → 策略选择 → 执行

权衡与选择

用策略：有多种可互换的算法、且需要在运行时切换时
用状态：行为随内部状态自动切换时——state-pattern-状态 的意图是”状态驱动行为”，策略的意图是”外部选择算法”
用模板方法：算法骨架固定、只有部分步骤变化时——template-method-pattern-模板方法 用继承，策略用组合
用命令：需要撤销、队列、延迟时——command-pattern-命令 封装”请求”，策略封装”算法”

常见陷阱



                  客户端必须知道所有策略 



策略的选择逻辑仍在客户端。如果策略很多，选择逻辑本身可能变复杂。可用工厂方法封装策略选择。





                  策略切换时机不受控 



如果策略在算法执行中途被另一个线程切换，可能导致不一致的结果。策略切换应发生在算法调用之间，而非调用期间。


