子类沙箱（Subclass Sandbox）
核心思想
基类提供一组”安全操作”方法，子类只组合调用这些方法来定义行为——子类不需要了解底层实现。基类充当”工具箱”，子类是”工匠”，工匠只使用工具箱提供的工具，不需要知道工具的制造工艺。

GPP 关键洞察：子类沙箱是”控制反转”在继承体系中的应用。传统继承中子类可以访问基类的一切；沙箱模式反过来限制子类只能访问基类暴露的操作集，从而实现隔离与解耦。

问题动机
子类直接访问全局状态/单例导致紧耦合——每新增一个子类就多一条对全局的依赖：
// 反面教材：子类直接调用 GameManager.xxx
public class FireballAbility : Ability
{
    public override void Activate()
    {
        // 子类直接访问各种全局单例——紧耦合
        GameManager.Instance.DealDamage(Target, 50);
        EffectManager.Instance.Play(&quot;Fireball&quot;, Target.transform.position);
        AudioManager.Instance.Play(&quot;explosion&quot;);
        CooldownManager.Instance.StartCooldown(this, 5f);
        LogManager.Instance.Log(&quot;Fireball cast&quot;);
    }
}

public class HealAbility : Ability
{
    public override void Activate()
    {
        // 又是另一堆全局访问
        GameManager.Instance.RestoreHealth(Caster, 40);
        EffectManager.Instance.Play(&quot;Heal&quot;, Caster.transform.position);
        AudioManager.Instance.Play(&quot;heal_sound&quot;);
        CooldownManager.Instance.StartCooldown(this, 3f);
    }
}

// 问题：
// 1. 每个子类都硬编码了对全局单例的依赖
// 2. 换一个管理器实现就要改所有子类
// 3. 无法单元测试（全局状态不可控）
// 4. 新增子类的人必须知道所有全局管理器的接口
这种写法的问题：

紧耦合：子类直接依赖全局单例，换实现就改所有子类
不可测试：全局状态不可控，无法单元测试子类行为
认知负担：新增子类的人必须知道所有全局管理器的接口
接口泄露：子类能访问全局管理器的所有方法，不限于需要的那几个

子类沙箱的核心动机：把底层系统的复杂性封装在基类中，子类只通过基类提供的”安全操作集”与外界交互。
结构图
classDiagram
    class AbilityBase {
        #PlayEffect(prefab, pos)
        #DealDamage(target, amount)
        #ApplyBuff(target, buff)
        #StartCooldown(duration)
        #PlaySound(clip)
        #SpawnProjectile(prefab, pos, dir)
        -_effectManager: EffectManager
        -_audioManager: AudioManager
        -_cooldownManager: CooldownManager
        +Activate()*
    }

    class FireballAbility {
        +Activate()
    }
    class HealAbility {
        +Activate()
    }
    class TeleportAbility {
        +Activate()
    }

    class EffectManager {
        +Play(prefab, pos)
    }
    class AudioManager {
        +Play(clip)
    }
    class CooldownManager {
        +StartCooldown(ability, duration)
    }

    AbilityBase &lt;|-- FireballAbility
    AbilityBase &lt;|-- HealAbility
    AbilityBase &lt;|-- TeleportAbility
    AbilityBase --&gt; EffectManager : 封装
    AbilityBase --&gt; AudioManager : 封装
    AbilityBase --&gt; CooldownManager : 封装

    note for FireballAbility &quot;子类只调用基类操作\n不直接访问全局管理器&quot;

参与者

























角色职责Unity/C# 对应基类（沙箱）提供操作集，封装底层服务引用Ability 基类、MonoBehaviour 虚方法子类（工匠）只组合调用基类操作，定义具体行为FireballAbility、HealAbility底层服务（被封装）被基类持有，子类不可直接访问EffectManager、AudioManager、物理引擎
工作原理
基础实现：技能沙箱
// 基类：沙箱——提供操作集
public abstract class Ability : MonoBehaviour
{
    // 沙箱操作：子类只能调用这些方法
    protected void PlayEffect(GameObject prefab, Vector3 pos)
        =&gt; EffectManager.Instance.Play(prefab, pos);

    protected void DealDamage(IDamageable target, float amount)
        =&gt; target.TakeDamage(amount);

    protected void ApplyBuff(IDamageable target, BuffData buff)
        =&gt; target.ApplyBuff(buff);

    protected void StartCooldown(float duration)
        =&gt; CooldownManager.Instance.Start(this, duration);

    protected void PlaySound(AudioClip clip)
        =&gt; AudioSource.PlayClipAtPoint(clip, transform.position);

    protected GameObject SpawnProjectile(GameObject prefab, Vector3 pos, Vector3 dir)
        =&gt; ProjectileManager.Instance.Spawn(prefab, pos, dir);

    // 子类实现此方法，只调用上面的操作
    public abstract void Activate(GameObject caster, GameObject target);
}

// 子类：只组合调用基类操作，不直接访问全局管理器
public class FireballAbility : Ability
{
    public override void Activate(GameObject caster, GameObject target)
    {
        DealDamage(target.GetComponent&lt;IDamageable&gt;(), 50);
        PlayEffect(Resources.Load&lt;GameObject&gt;(&quot;Effects/Fireball&quot;), target.transform.position);
        PlaySound(Resources.Load&lt;AudioClip&gt;(&quot;Sounds/Explosion&quot;));
        StartCooldown(5f);
    }
}

public class HealAbility : Ability
{
    public override void Activate(GameObject caster, GameObject target)
    {
        var damageable = caster.GetComponent&lt;IDamageable&gt;();
        damageable.RestoreHealth(40);
        PlayEffect(Resources.Load&lt;GameObject&gt;(&quot;Effects/Heal&quot;), caster.transform.position);
        PlaySound(Resources.Load&lt;AudioClip&gt;(&quot;Sounds/Heal&quot;));
        StartCooldown(3f);
    }
}
服务注入式沙箱
基类通过构造函数接收服务引用，而非依赖全局单例：
public abstract class Ability
{
    // 基类持有服务引用，子类不可见
    private readonly IEffectService _effects;
    private readonly IAudioService _audio;
    private readonly ICooldownService _cooldowns;

    protected Ability(IEffectService effects, IAudioService audio, ICooldownService cooldowns)
    {
        _effects = effects;
        _audio = audio;
        _cooldowns = cooldowns;
    }

    // 沙箱操作
    protected void PlayEffect(string effectId, Vector3 pos) =&gt; _effects.Play(effectId, pos);
    protected void PlaySound(string soundId) =&gt; _audio.Play(soundId);
    protected void StartCooldown(float duration) =&gt; _cooldowns.Start(this, duration);

    public abstract void Activate(GameObject caster, GameObject target);
}

// 工厂创建时注入依赖
public class AbilityFactory
{
    private readonly IEffectService _effects;
    private readonly IAudioService _audio;
    private readonly ICooldownService _cooldowns;

    public AbilityFactory(IEffectService effects, IAudioService audio, ICooldownService cooldowns)
    {
        _effects = effects;
        _audio = audio;
        _cooldowns = cooldowns;
    }

    public Ability Create(string abilityName)
    {
        return abilityName switch
        {
            &quot;Fireball&quot; =&gt; new FireballAbility(_effects, _audio, _cooldowns),
            &quot;Heal&quot; =&gt; new HealAbility(_effects, _audio, _cooldowns),
            _ =&gt; throw new ArgumentException($&quot;Unknown ability: {abilityName}&quot;)
        };
    }
}



                  服务注入 vs 全局单例 



服务注入让基类的依赖显式化、可测试。全局单例版本更简单但不可测试。项目初期用全局单例快速迭代，后期重构为服务注入。参见 service-locator-服务定位 和 singleton-pattern-单例。


游戏开发深度
MonoBehaviour 作为沙箱基类
Unity 的 MonoBehaviour 就是子类沙箱的经典实现——基类提供的操作钩子就是沙箱操作：
// MonoBehaviour 提供的&quot;沙箱操作&quot;（部分）
public class MonoBehaviour : Component
{
    // 生命周期钩子——子类重写这些方法定义行为
    protected virtual void Awake() { }
    protected virtual void OnEnable() { }
    protected virtual void Start() { }
    protected virtual void Update() { }
    protected virtual void FixedUpdate() { }
    protected virtual void LateUpdate() { }
    protected virtual void OnDisable() { }
    protected virtual void OnDestroy() { }

    // 物理钩子——子类不需要知道物理引擎的实现
    protected virtual void OnCollisionEnter(Collision other) { }
    protected virtual void OnTriggerEnter(Collider other) { }

    // 子类不能直接操作引擎内部——只能通过基类暴露的方法
    // 如 transform.position, GetComponent&lt;T&gt;(), StartCoroutine() 等
}
子类（我们的脚本）只组合调用这些操作，不需要了解引擎内部调度机制。参见 monobehaviour-lifecycle-生命周期。
敌人 AI 沙箱
敌人 AI 基类提供一组行为操作，子类只组合调用：
public abstract class EnemyAI : MonoBehaviour
{
    protected Transform Transform =&gt; transform;
    protected GameObject Player =&gt; GameManager.Instance.Player;

    // 沙箱操作：移动
    protected void MoveToward(Vector3 target, float speed)
    {
        var dir = (target - Transform.position).normalized;
        Transform.position += dir * speed * Time.deltaTime;
    }

    // 沙箱操作：攻击
    protected void Attack(float damage, float range)
    {
        if (Vector3.Distance(Transform.position, Player.transform.position) &lt;= range)
            Player.GetComponent&lt;IDamageable&gt;().TakeDamage(damage);
    }

    // 沙箱操作：播放动画
    protected void PlayAnimation(string trigger)
        =&gt; GetComponent&lt;Animator&gt;().SetTrigger(trigger);

    // 沙箱操作：生成效果
    protected void SpawnEffect(GameObject prefab, Vector3 pos)
        =&gt; Instantiate(prefab, pos, Quaternion.identity);

    // 沙箱操作：巡逻
    protected void Patrol(Vector3 center, float radius, ref float angle, float speed)
    {
        angle += speed * Time.deltaTime;
        var offset = new Vector3(Mathf.Cos(angle) * radius, 0, Mathf.Sin(angle) * radius);
        MoveToward(center + offset, speed);
    }

    // 子类实现：自由组合上面的操作
    protected abstract void OnThink();
}

// 巡逻兵：巡逻 → 追击 → 攻击
public class PatrolEnemyAI : EnemyAI
{
    private float _patrolAngle;

    protected override void OnThink()
    {
        var distToPlayer = Vector3.Distance(Transform.position, Player.transform.position);

        if (distToPlayer &lt;= 2f)
        {
            PlayAnimation(&quot;Attack&quot;);
            Attack(10f, 2f);
        }
        else if (distToPlayer &lt;= 10f)
        {
            PlayAnimation(&quot;Run&quot;);
            MoveToward(Player.transform.position, 3f);
        }
        else
        {
            PlayAnimation(&quot;Walk&quot;);
            Patrol(transform.position, 5f, ref _patrolAngle, 1f);
        }
    }
}

// 远程法师：保持距离 → 施法
public class MageEnemyAI : EnemyAI
{
    protected override void OnThink()
    {
        var distToPlayer = Vector3.Distance(Transform.position, Player.transform.position);

        if (distToPlayer &lt;= 3f)
        {
            // 太近 → 后退
            MoveToward(Transform.position - (Player.transform.position - Transform.position).normalized, 4f);
            PlayAnimation(&quot;Retreat&quot;);
        }
        else if (distToPlayer &lt;= 15f)
        {
            PlayAnimation(&quot;Cast&quot;);
            SpawnEffect(Resources.Load&lt;GameObject&gt;(&quot;Effects/Fireball&quot;), Transform.position);
            Attack(25f, 15f);
        }
    }
}
技能沙箱：DealDamage / ApplyBuff / CreateProjectile
public abstract class Skill : MonoBehaviour
{
    [SerializeField] protected float cooldown = 1f;
    [SerializeField] protected float manaCost = 10f;

    // 沙箱操作：造成伤害
    protected void DealDamage(GameObject target, float amount)
        =&gt; target.GetComponent&lt;IDamageable&gt;()?.TakeDamage(amount);

    // 沙箱操作：施加 Buff
    protected void ApplyBuff(GameObject target, BuffData buff)
        =&gt; target.GetComponent&lt;IBuffable&gt;()?.ApplyBuff(buff);

    // 沙箱操作：创建投射物
    protected void CreateProjectile(GameObject prefab, Vector3 origin, Vector3 direction, float speed)
    {
        var projectile = Instantiate(prefab, origin, Quaternion.LookRotation(direction));
        projectile.GetComponent&lt;Rigidbody&gt;().linearVelocity = direction * speed;
    }

    // 沙箱操作：范围伤害
    protected void DealAreaDamage(Vector3 center, float radius, float damage)
    {
        var hits = Physics.OverlapSphere(center, radius);
        foreach (var hit in hits)
            hit.GetComponent&lt;IDamageable&gt;()?.TakeDamage(damage);
    }

    // 沙箱操作：消耗法力
    protected bool TryConsumeMana(float amount)
        =&gt; GetComponent&lt;ManaPool&gt;()?.TryConsume(amount) ?? false;

    public abstract void Execute(GameObject caster, GameObject target);
}

// 子类：自由组合沙箱操作
public class FireballSkill : Skill
{
    [SerializeField] private GameObject projectilePrefab;
    [SerializeField] private BuffData burnBuff;

    public override void Execute(GameObject caster, GameObject target)
    {
        if (!TryConsumeMana(manaCost)) return;

        var dir = (target.transform.position - caster.transform.position).normalized;
        CreateProjectile(projectilePrefab, caster.transform.position, dir, 20f);
        DealDamage(target, 50);
        ApplyBuff(target, burnBuff);
    }
}
与模板方法模式的对比
子类沙箱和模板方法都涉及基类与子类的分工，但方向相反：






























维度模板方法子类沙箱控制方向基类定流程，子类填空基类提供工具，子类自由组合灵活性低（流程固定）高（子类自主决定调用顺序和组合）约束方式基类调用子类的抽象方法子类调用基类的 protected 方法典型场景固定流程（初始化步骤、数据处理管线）自由行为（技能、敌人 AI）
// 模板方法：基类定流程，子类填空
public abstract class DataProcessor
{
    public void Process()  // 固定流程
    {
        var data = LoadData();        // 步骤 1
        var result = Transform(data); // 步骤 2（子类实现）
        SaveData(result);             // 步骤 3
    }
    protected abstract float[] Transform(float[] data);
}

// 子类沙箱：基类提供工具，子类自由组合
public abstract class Ability
{
    protected void DealDamage(...) { }
    protected void PlayEffect(...) { }
    protected void ApplyBuff(...) { }
    public abstract void Activate(); // 子类自由组合上面的操作
}
参见 template-method-pattern-模板方法。
变体与演进






























变体说明适用场景全局单例式沙箱基类内部访问全局单例，子类不可见简单项目、快速原型服务注入式沙箱基类通过构造函数接收服务引用可测试架构、大型项目接口式沙箱基类操作集提取为接口，多种实现需要切换底层服务时组合式沙箱多个小组沙箱替代一个大沙箱操作集按领域拆分
接口式沙箱
将基类的操作集提取为接口，可以有多种实现：
// 操作集接口
public interface IAbilityOperations
{
    void DealDamage(IDamageable target, float amount);
    void PlayEffect(string effectId, Vector3 pos);
    void ApplyBuff(IDamageable target, BuffData buff);
    void StartCooldown(IAbility ability, float duration);
}

// 生产实现
public class ProductionAbilityOps : IAbilityOperations { /* 真实调用 */ }

// 测试实现
public class TestAbilityOps : IAbilityOperations
{
    public List&lt;string&gt; Log = new();
    public void DealDamage(IDamageable target, float amount) =&gt; Log.Add($&quot;Damage:{amount}&quot;);
    public void PlayEffect(string id, Vector3 pos) =&gt; Log.Add($&quot;Effect:{id}&quot;);
    public void ApplyBuff(IDamageable target, BuffData buff) =&gt; Log.Add($&quot;Buff:{buff.name}&quot;);
    public void StartCooldown(IAbility ability, float duration) =&gt; Log.Add($&quot;Cooldown:{duration}&quot;);
}

// 基类注入操作集
public abstract class Ability
{
    protected IAbilityOperations Ops { get; }
    protected Ability(IAbilityOperations ops) =&gt; Ops = ops;
    public abstract void Activate(GameObject caster, GameObject target);
}

// 单元测试
[Test]
public void Fireball_Deals_50_Damage()
{
    var ops = new TestAbilityOps();
    var ability = new FireballAbility(ops);
    ability.Activate(caster, target);
    Assert.IsTrue(ops.Log.Contains(&quot;Damage:50&quot;));
}
反模式



                  基类操作集膨胀（God Base Class） 



随着需求增长，基类的 protected 方法越来越多，最终变成”上帝基类”——所有系统都能操作，所有子类都能访问。控制操作集规模的关键：按领域拆分多个基类（如 CombatAbility、MovementAbility、UtilityAbility），或当操作集超过 ~10 个方法时考虑迁移到 type-object-类型对象。参见 facade-pattern-外观。





                  子类绕过沙箱直接访问全局 



沙箱的安全前提是”子类只调用基类暴露的操作”。如果子类绕过沙箱直接访问全局管理器（如 GameManager.Instance.xxx），沙箱的隔离性就被破坏了。代码审查时应检查子类是否使用了 Instance 或 FindObjectOfType 等全局访问手段。参见 singleton-pattern-单例。





                  基类操作集过小——子类无法表达需要的行为 



如果基类提供的操作不足以覆盖子类的需求，子类要么绕过沙箱（反模式），要么向基类申请加操作（基类膨胀）。解决方法：提供”扩展点”机制，允许子类注册自定义操作，同时保持核心操作集的稳定。参见 type-object-类型对象 的”数据定义行为”思路。


权衡与选择

用子类沙箱：行为由代码定义，子类数量有限，需要隔离底层复杂性时
用模板方法：行为流程固定，子类只需填充步骤时——template-method-pattern-模板方法
用类型对象：行为差异由数据决定而非代码逻辑时——type-object-类型对象
用字节码：行为需要运行时可编程、策划可编辑时——bytecode-字节码
用外观模式：需要简化子系统接口但不需要继承体系时——facade-pattern-外观

