访问者（Visitor）
核心思想
将算法与对象结构分离。在不修改对象类的前提下，通过访问者为对象结构中的各类型元素定义新操作。核心机制是双重分派（Double Dispatch）——运行时根据访问者和元素的实际类型选择正确的方法。
结构图
classDiagram
    class IVisitor {
        &lt;&lt;interface&gt;&gt;
        +Visit(element: ConcreteElementA) void
        +Visit(element: ConcreteElementB) void
        +Visit(element: ConcreteElementC) void
    }
    class ConcreteVisitorA {
        +Visit(element: ConcreteElementA) void
        +Visit(element: ConcreteElementB) void
        +Visit(element: ConcreteElementC) void
    }
    class ConcreteVisitorB {
        +Visit(element: ConcreteElementA) void
        +Visit(element: ConcreteElementB) void
        +Visit(element: ConcreteElementC) void
    }
    class IElement {
        &lt;&lt;interface&gt;&gt;
        +Accept(visitor: IVisitor) void
    }
    class ConcreteElementA {
        +Accept(visitor: IVisitor) void
        +OperationA() string
    }
    class ConcreteElementB {
        +Accept(visitor: IVisitor) void
        +OperationB() string
    }
    class ConcreteElementC {
        +Accept(visitor: IVisitor) void
        +OperationC() string
    }
    class ObjectStructure {
        -_elements: List~IElement~
        +Accept(visitor: IVisitor) void
        +Add(element: IElement) void
    }

    IVisitor &lt;|.. ConcreteVisitorA
    IVisitor &lt;|.. ConcreteVisitorB
    IElement &lt;|.. ConcreteElementA
    IElement &lt;|.. ConcreteElementB
    IElement &lt;|.. ConcreteElementC
    ConcreteElementA --&gt; IVisitor : Accept 调用 Visit(this)
    ConcreteElementB --&gt; IVisitor : Accept 调用 Visit(this)
    ConcreteElementC --&gt; IVisitor : Accept 调用 Visit(this)
    ObjectStructure o--&gt; IElement : _elements
    ObjectStructure --&gt; IVisitor : 遍历并 Accept

sequenceDiagram
    participant Client
    participant Visitor as ConcreteVisitor
    participant Element as ConcreteElementA
    participant Structure as ObjectStructure

    Note over Client,Structure: 双重分派过程

    Client-&gt;&gt;Structure: Accept(visitor)
    Structure-&gt;&gt;Element: Accept(visitor) [第一重分派：按元素类型]
    Element-&gt;&gt;Visitor: Visit(this) [第二重分派：按访问者类型]
    Note over Visitor: 编译器选择 Visit(ConcreteElementA) 重载
    Visitor-&gt;&gt;Visitor: 执行类型特定逻辑

问题动机
没有访问者时，对不同类型对象添加操作需要在每个对象类中加方法——违反开闭原则：
// 反面教材：对一组不同类型对象添加操作的困难
public interface IMapObject { }

public class Treasure : IMapObject
{
    public int Gold { get; set; }
    // 每新增一种操作，就要在这里加方法
    public string Serialize() =&gt; $&quot;Treasure:{Gold}&quot;;
    public void ApplyDamage(int dmg) { /* 宝箱被打坏？ */ }
    public void Render(MapRenderer renderer) { /* 渲染逻辑 */ }
}

public class Trap : IMapObject
{
    public int Damage { get; set; }
    public string Serialize() =&gt; $&quot;Trap:{Damage}&quot;;
    public void ApplyDamage(int dmg) { /* 陷阱被打坏？ */ }
    public void Render(MapRenderer renderer) { /* 渲染逻辑 */ }
}

public class Enemy : IMapObject
{
    public int Hp { get; set; }
    public string Serialize() =&gt; $&quot;Enemy:{Hp}&quot;;
    public void ApplyDamage(int dmg) { Hp -= dmg; }
    public void Render(MapRenderer renderer) { /* 渲染逻辑 */ }
}

// 更糟的方案：用 if-else 类型判断
public class MapProcessor
{
    public void ProcessAll(IEnumerable&lt;IMapObject&gt; objects)
    {
        foreach (var obj in objects)
        {
            if (obj is Treasure t) ProcessTreasure(t);
            else if (obj is Trap tr) ProcessTrap(tr);
            else if (obj is Enemy e) ProcessEnemy(e);
            // 每新增一种元素类型，所有 if-else 链都要改
            // 每新增一种操作，就要写新的 if-else 链
        }
    }
}
这种写法的问题：

操作侵入元素类：每新增一种操作，所有元素类都要加方法
类型判断散落：if-else / switch 类型判断遍布代码，新增类型要改所有判断点
无法统一遍历：不同类型的操作逻辑分散，无法统一管理
编译期无保障：if-else 链漏掉一种类型不会有编译错误

访问者的核心动机：让操作独立于对象结构变化——新增操作只需添加一个 Visitor 类，不修改任何元素类。
参与者



































角色职责Unity/C# 对应IVisitor为每种元素声明 Visit 方法IMapVisitor、IDamageVisitor 接口ConcreteVisitor实现类型特定的操作逻辑MapSerializer、DamageApplierIElement声明 Accept 方法（入口）IMapObject、IStatusEffectConcreteElement实现 Accept，调用 visitor.Visit(this)Treasure、Trap、EnemyObjectStructure持有元素集合，提供遍历入口Map、StatusEffectList



                  双重分派的工作原理 



C# 的方法重载在编译期根据声明类型选择重载版本。visitor.Visit((IElement)element) 永远调用 Visit(IElement)，而非 Visit(Treasure)。双重分派绕过这个限制：

第一重分派：element.Accept(visitor) —— 运行时按 element 的实际类型选择 Treasure.Accept()
第二重分派：visitor.Visit(this) —— 此时 this 的编译期类型是 Treasure，所以选择 Visit(Treasure) 重载



工作原理
基础实现：地图对象系统
// 元素接口
public interface IMapObject
{
    void Accept(IMapVisitor visitor);
}

// 具体元素
public class Treasure : IMapObject
{
    public int Gold { get; set; }
    public void Accept(IMapVisitor visitor) =&gt; visitor.Visit(this);
}

public class Trap : IMapObject
{
    public int Damage { get; set; }
    public void Accept(IMapVisitor visitor) =&gt; visitor.Visit(this);
}

public class Enemy : IMapObject
{
    public int Hp { get; set; }
    public void Accept(IMapVisitor visitor) =&gt; visitor.Visit(this);
}

// 访问者接口：为每种元素定义一个方法
public interface IMapVisitor
{
    void Visit(Treasure treasure);
    void Visit(Trap trap);
    void Visit(Enemy enemy);
}

// 具体访问者：序列化
public class MapSerializer : IMapVisitor
{
    public string Result { get; private set; } = &quot;&quot;;

    public void Visit(Treasure t) =&gt; Result += $&quot;Treasure:{t.Gold} &quot;;
    public void Visit(Trap t) =&gt; Result += $&quot;Trap:{t.Damage} &quot;;
    public void Visit(Enemy e) =&gt; Result += $&quot;Enemy:{e.Hp} &quot;;
}

// 具体访问者：伤害应用
public class DamageVisitor : IMapVisitor
{
    private readonly int _damage;
    public DamageVisitor(int damage) =&gt; _damage = damage;

    public void Visit(Treasure t) { /* 宝箱不受伤害 */ }
    public void Visit(Trap t) { /* 陷阱不受伤害 */ }
    public void Visit(Enemy e) =&gt; e.Hp -= _damage; // 只有敌人受伤
}

// 对象结构
public class Map
{
    private readonly List&lt;IMapObject&gt; _objects = new();
    public void Add(IMapObject obj) =&gt; _objects.Add(obj);
    public void Accept(IMapVisitor visitor)
    {
        foreach (var obj in _objects) obj.Accept(visitor);
    }
}

// 使用
var map = new Map();
map.Add(new Treasure { Gold = 100 });
map.Add(new Trap { Damage = 30 });
map.Add(new Enemy { Hp = 50 });

// 序列化——新增操作不需要改任何元素类
var serializer = new MapSerializer();
map.Accept(serializer);
Debug.Log(serializer.Result); // &quot;Treasure:100 Trap:30 Enemy:50 &quot;

// 伤害——另一个操作
map.Accept(new DamageVisitor(20)); // 只有敌人受伤
返回值的访问者
当访问者需要计算并返回结果时，用累加器模式：
public class TotalValueVisitor : IMapVisitor
{
    public int TotalValue { get; private set; }

    public void Visit(Treasure t) =&gt; TotalValue += t.Gold;
    public void Visit(Trap t) { /* 陷阱无价值 */ }
    public void Visit(Enemy e) =&gt; TotalValue += e.Hp * 2; // 击杀奖励
}

var valuator = new TotalValueVisitor();
map.Accept(valuator);
Debug.Log($&quot;Map total value: {valuator.TotalValue}&quot;);
游戏开发深度
伤害类型分发系统
不同伤害类型对不同目标组件有不同效果——访问者天然适合这种”按类型分发”的场景：
// 元素：可受伤的组件
public interface IDamageable { void Accept(IDamageType type); }

public class Health : IDamageable
{
    public int CurrentHp;
    public void Accept(IDamageType type) =&gt; type.Visit(this);
}

public class Shield : IDamageable
{
    public int CurrentShield;
    public void Accept(IDamageType type) =&gt; type.Visit(this);
}

public class Armor : IDamageable
{
    public int Reduction;
    public void Accept(IDamageType type) =&gt; type.Visit(this);
}

// 访问者：不同伤害类型
public interface IDamageType
{
    void Visit(Health health);
    void Visit(Shield shield);
    void Visit(Armor armor);
}

public class PhysicalDamage : IDamageType
{
    public int Amount;
    public void Visit(Health h) =&gt; h.CurrentHp -= Amount;
    public void Visit(Shield s) { s.CurrentShield -= Amount; /* 护盾全额吸收 */ }
    public void Visit(Armor a) { Amount = Mathf.Max(1, Amount - a.Reduction); /* 护甲减伤 */ }
}

public class MagicDamage : IDamageType
{
    public int Amount;
    public void Visit(Health h) =&gt; h.CurrentHp -= Amount;
    public void Visit(Shield s) { /* 魔法伤害穿透护盾 */ }
    public void Visit(Armor a) { /* 魔法伤害无视护甲 */ }
}

public class TrueDamage : IDamageType
{
    public int Amount;
    public void Visit(Health h) =&gt; h.CurrentHp -= Amount;
    public void Visit(Shield s) { /* 真实伤害穿透一切 */ }
    public void Visit(Armor a) { /* 无视护甲 */ }
}



                  伤害类型分发 vs 责任链 



伤害类型分发（按类型选择逻辑）适合访问者；伤害管线（顺序处理、可中断）适合责任链。参见 chain-of-responsibility-责任链。


序列化/反序列化
按类型写不同格式——序列化器是典型的 Visitor：
public interface ISaveVisitor
{
    void Visit(PlayerState player);
    void Visit(EnemyState enemy);
    void Visit(WorldState world);
}

public class JsonSaveVisitor : ISaveVisitor
{
    public JObject Result { get; } = new();

    public void Visit(PlayerState p)
    {
        Result[&quot;player&quot;] = new JObject
        {
            [&quot;hp&quot;] = p.Hp,
            [&quot;position&quot;] = p.Position.ToJson()
        };
    }

    public void Visit(EnemyState e)
    {
        var arr = (JArray)Result.GetOrAdd(&quot;enemies&quot;, _ =&gt; new JArray());
        arr.Add(new JObject { [&quot;type&quot;] = e.Type, [&quot;hp&quot;] = e.Hp });
    }

    public void Visit(WorldState w)
    {
        Result[&quot;world&quot;] = new JObject { [&quot;time&quot;] = w.TimeOfDay };
    }
}
地图编辑器工具
不同编辑工具对选中对象执行不同操作：
public interface IEditorTool : IMapVisitor
{
    string ToolName { get; }
}

public class DeleteTool : IEditorTool
{
    public string ToolName =&gt; &quot;Delete&quot;;
    private readonly List&lt;IMapObject&gt; _toDelete = new();

    public void Visit(Treasure t) =&gt; _toDelete.Add(t);
    public void Visit(Trap t) =&gt; _toDelete.Add(t);
    public void Visit(Enemy e) =&gt; _toDelete.Add(e);

    public void Apply(Map map)
    {
        foreach (var obj in _toDelete) map.Remove(obj);
        _toDelete.Clear();
    }
}

public class DuplicateTool : IEditorTool
{
    public string ToolName =&gt; &quot;Duplicate&quot;;
    private readonly List&lt;IMapObject&gt; _toAdd = new();

    public void Visit(Treasure t) =&gt; _toAdd.Add(new Treasure { Gold = t.Gold });
    public void Visit(Trap t) =&gt; _toAdd.Add(new Trap { Damage = t.Damage });
    public void Visit(Enemy e) =&gt; _toAdd.Add(new Enemy { Hp = e.Hp });

    public void Apply(Map map)
    {
        foreach (var obj in _toAdd) map.Add(obj);
        _toAdd.Clear();
    }
}
ECS 中 Visitor 模式的退化
在 DOTS 的 dots-ecs-数据导向 架构中，System 天然按 Component 类型遍历 Entity，不需要双重分派：
// ECS 中不需要 Visitor——System 直接按类型查询
partial struct DamageSystem : ISystem
{
    void OnUpdate(ref SystemState state)
    {
        // 对所有有 Health 组件的 Entity 应用伤害
        // 不需要 Accept/Visit，因为查询本身就是类型分派
        foreach (var health in SystemAPI.Query&lt;RefRW&lt;Health&gt;&gt;())
        {
            health.ValueRW.Value -= 10;
        }

        // 对所有有 Shield 组件的 Entity 另行处理
        foreach (var shield in SystemAPI.Query&lt;RefRW&lt;Shield&gt;&gt;())
        {
            shield.ValueRW.Value -= 5;
        }
    }
}



                  ECS 的查询代替了双重分派 



Visitor 模式的核心问题是”如何按类型选择操作”。ECS 的 SystemAPI.Query&lt;RefRW&lt;T&gt;&gt; 天然按 Component 类型筛选，每个 System 就是一个”Visitor”，每个 Query 就是一个”Visit”方法。双重分派在数据驱动架构中退化为查询。参见 dots-ecs-数据导向。


变体与演进
用 C# dynamic 实现动态分派
用 dynamic 关键字绕过双重分派的样板代码——运行时根据实际类型选择方法重载：
// 动态分派：不需要 Accept 方法，不需要元素类修改
public class DynamicVisitor
{
    public void ProcessAll(IEnumerable&lt;IMapObject&gt; objects)
    {
        foreach (var obj in objects)
            Visit((dynamic)obj); // 运行时按实际类型选择重载
    }

    private void Visit(Treasure t) { /* 处理宝箱 */ }
    private void Visit(Trap t) { /* 处理陷阱 */ }
    private void Visit(Enemy e) { /* 处理敌人 */ }

    // 兜底：未知类型
    private void Visit(object obj) =&gt; Debug.LogWarning($&quot;Unknown type: {obj.GetType()}&quot;);
}



                  dynamic 的代价 



dynamic 使用 DLR（Dynamic Language Runtime），每次调用有反射开销。热路径中不适用。此外，编译期无法检查类型安全——新增元素类型不会触发编译错误，只有运行时兜底。


用 pattern matching 替代 Visitor（C# 8+）
C# 8.0+ 的 switch expression 提供了更简洁的类型分派：
// C# 8+ switch expression：替代 Visitor 的类型分派
public static string Serialize(IMapObject obj) =&gt; obj switch
{
    Treasure t =&gt; $&quot;Treasure:{t.Gold}&quot;,
    Trap tr =&gt; $&quot;Trap:{tr.Damage}&quot;,
    Enemy e =&gt; $&quot;Enemy:{e.Hp}&quot;,
    _ =&gt; $&quot;Unknown:{obj.GetType().Name}&quot;
};

// C# 9+ 带属性模式：更精细的匹配
public static string Describe(IMapObject obj) =&gt; obj switch
{
    Treasure { Gold: &gt; 1000 } =&gt; &quot;Rare treasure&quot;,
    Treasure t =&gt; $&quot;Common treasure ({t.Gold} gold)&quot;,
    Trap { Damage: &gt; 50 } =&gt; &quot;Lethal trap&quot;,
    Trap t =&gt; $&quot;Minor trap ({t.Damage} dmg)&quot;,
    Enemy { Hp: &lt;= 0 } =&gt; &quot;Dead enemy&quot;,
    Enemy e =&gt; $&quot;Enemy with {e.Hp} HP&quot;,
    _ =&gt; &quot;Unknown&quot;
};





























方式优点缺点类型安全经典 Visitor编译期类型安全、OCP（新增操作）新增元素类型要改所有 Visitor编译期dynamic无样板代码、元素类不需要改反射开销、运行时错误运行时pattern matching简洁、编译期穷举检查新增元素类型要改所有 switch编译期（带穷举警告）



                  选择建议 



元素类型稳定、操作频繁新增 → 经典 Visitor。元素和操作都频繁变化 → pattern matching（更灵活）。原型/工具代码 → dynamic（最快实现）。


泛型 Visitor
当多个 Visitor 有公共逻辑时，用泛型基类减少重复：
// 泛型 Visitor 基类：默认实现为空操作
public abstract class MapVisitorBase : IMapVisitor
{
    public virtual void Visit(Treasure t) { }
    public virtual void Visit(Trap t) { }
    public virtual void Visit(Enemy e) { }

    // 辅助方法：遍历并访问
    public void VisitAll(IEnumerable&lt;IMapObject&gt; objects)
    {
        foreach (var obj in objects) obj.Accept(this);
    }
}

// 具体 Visitor 只覆盖关心的类型
public class GoldCollector : MapVisitorBase
{
    public int TotalGold { get; private set; }
    public override void Visit(Treasure t) =&gt; TotalGold += t.Gold;
    // Trap 和 Enemy 使用默认空实现
}
反模式



                  元素类型频繁变化时使用 Visitor 



Visitor 的最大限制：每新增一种元素类型，所有 Visitor 接口和具体 Visitor 都要修改。如果元素类型频繁变化（如每周新增一种地图对象），维护成本会急剧上升。判断标准：元素类型是否比操作更稳定？如果是，用 Visitor；如果否，用 pattern matching 或策略模式。





                  Visitor 破坏封装 



Visitor 需要访问元素的内部数据（如 Treasure.Gold、Enemy.Hp），这意味着元素必须暴露足够的数据供 Visitor 操作。如果元素本应隐藏内部实现，Visitor 会迫使你打破封装。解决方案：元素提供”足够但不过度”的接口——暴露”访问者需要的数据”，隐藏”内部实现细节”。





                  循环引用导致 Visitor 与元素紧耦合 



如果 Visitor 在 Visit 方法中回调元素的公共方法修改其状态，而元素又在 Accept 中依赖 Visitor 的特定类型，循环依赖会让两者都无法独立变化。Visitor 应该是”只读遍历+外部计算”，尽量避免在 Visit 中修改元素状态。


权衡与选择

用访问者：对象结构稳定、需要频繁添加新操作时
用策略：操作可替换但不需要按类型分派时
用命令：操作需要撤销/队列时
用 pattern matching：元素类型和操作都频繁变化、需要灵活组合时
用 ECS 查询：在 DOTS 架构中，System 查询天然替代 Visitor

相关

