Awaitable vs UniTask 对比
Awaitable 是官方内置方案（零依赖，适合公共库和简单场景），UniTask 功能更全（WhenAll/异步流/细粒度 PlayerLoopTiming）。Awaitable 不等于 UniTask 替代品，而是 Coroutine 的 async/await 等价物。详细对比见 Awaitable 与 UniTask 对比。
Cancellation 详解
Unity Awaitable 使用 .NET CancellationToken 实现协作式取消，通过 destroyCancellationToken 绑定对象生命周期、CreateLinkedTokenSource 组合多取消源。finally 块保证资源清理，比 StopCoroutine 更安全。Awaitable.Cancel() 因池化风险不推荐使用。详细说明见 Awaitable Cancellation 详解。
常见模式
加载界面
public class LoadingScreen : MonoBehaviour
{
    [SerializeField] private GameObject _screenUI;
    [SerializeField] private Slider _progressBar;

    public async Awaitable ShowUntilCompleteAsync(
        Func&lt;Awaitable&gt; workload, CancellationToken ct = default)
    {
        _screenUI.SetActive(true);
        _progressBar.value = 0f;

        var loadTask = workload();

        // 动画进度条
        while (!loadTask.GetAwaiter().IsCompleted)
        {
            ct.ThrowIfCancellationRequested();
            _progressBar.value = Mathf.MoveTowards(
                _progressBar.value, 1f, Time.deltaTime * 0.5f);
            await Awaitable.NextFrameAsync(ct);
        }

        await loadTask;
        _progressBar.value = 1f;
        await Awaitable.WaitForSecondsAsync(0.3f, ct);
        _screenUI.SetActive(false);
    }
}
对话系统
public class DialogueSystem : MonoBehaviour
{
    private AwaitableCompletionSource _lineCompleted;

    public async Awaitable RunDialogueAsync(
        DialogueScript script, CancellationToken ct)
    {
        foreach (var line in script.Lines)
        {
            ShowLine(line.Text);
            _lineCompleted = new AwaitableCompletionSource();

            // 等待玩家点击继续或超时
            // 注意：Awaitable 没有 WhenAny，需要通过 AsTask() 借助 Task.WhenAny
            var clickTask = _lineCompleted.Awaitable.AsTask();
            var timeoutTask = Awaitable.WaitForSecondsAsync(line.DisplayTime, ct).AsTask();
            var completedTask = await Task.WhenAny(clickTask, timeoutTask);
            if (completedTask == clickTask)
            {
                // 玩家点击了继续
            }
        }
    }

    // 绑定到 UI 按钮的 OnClick
    public void OnContinueClicked() =&gt; _lineCompleted?.TrySetResult();
}
